
const HTML = "<!doctype html>\n<html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"theme-color\" content=\"#0b0d15\"><title>RivaL · Evidence Board</title>\n<style>\n:root{color-scheme:dark;--bg:#080b12;--panel:#101522;--panel2:#171e2c;--edge:#283345;--text:#eef3fc;--muted:#93a1b6;--violet:#ac94ff;--cyan:#6ddee5;--red:#fb8c9e;--amber:#e9bb6c;--green:#88dec0}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 10% -20%,#26214155,transparent 50%),var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,'Segoe UI',sans-serif}button,input,select{font:inherit}button{cursor:pointer}a{color:var(--cyan);text-decoration:none}a:hover{text-decoration:underline}.shell{max-width:1500px;margin:auto;padding:0 20px 100px}.header{position:sticky;z-index:10;top:0;padding:16px 0;background:#080b12ee;backdrop-filter:blur(18px);border-bottom:1px solid var(--edge);margin-bottom:20px}.headerin{max-width:1500px;margin:auto;padding:0 20px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;align-items:center;gap:12px}.logo{height:38px;width:38px;display:grid;place-items:center;background:#a08aff23;color:var(--violet);border:1px solid #8c7bcb77;border-radius:12px;font-weight:900;font-size:21px}.name{font-size:20px;font-weight:800;letter-spacing:-.6px}.sub{font-size:11px;color:var(--muted)}.right{display:flex;align-items:center;gap:9px}.pill,.tag{display:inline-flex;align-items:center;gap:4px;border-radius:99px;border:1px solid var(--edge);padding:4px 9px;font-size:11px;font-weight:700;color:var(--muted);white-space:nowrap}.pill{background:var(--panel)}.ok{color:var(--green);border-color:#26604f}.warn{color:var(--amber);border-color:#775932}.bad{color:var(--red);border-color:#773946}.pending{color:var(--violet);border-color:#59468d}.action{background:#242d41;color:var(--text);border:1px solid #40506a;padding:9px 12px;border-radius:10px;font-weight:700}.action:hover{background:#34415a}.tabs{display:flex;gap:8px;overflow:auto;padding:4px 0 18px;scrollbar-width:none}.tab{border:1px solid var(--edge);background:var(--panel);color:var(--muted);padding:10px 16px;border-radius:10px;white-space:nowrap;font-weight:700}.tab.active{color:#fff;border-color:#9f83f0;background:#43386b}.eyebrow{font-size:11px;letter-spacing:1.8px;font-weight:800;color:var(--violet);text-transform:uppercase}.pagehead{display:flex;justify-content:space-between;gap:10px;align-items:end;margin:0 0 18px}.pagehead h1{margin:3px 0 2px;font-size:27px;letter-spacing:-1px}.muted{color:var(--muted)}.tiny{font-size:11px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px}.kpi{border:1px solid var(--edge);border-radius:14px;background:linear-gradient(130deg,#181c2c,#101520);padding:15px;min-height:110px}.kpi .val{font-size:24px;font-weight:800;line-height:1.4}.kpi .label{color:var(--muted);font-size:12px}.section{margin-top:25px}.secthead{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 12px}.secthead h2{margin:0;font-size:16px}.card{background:var(--panel);border:1px solid var(--edge);border-radius:14px;padding:16px}.two{display:grid;grid-template-columns:1.5fr 1fr;gap:14px}.summary{color:var(--muted);font-size:13px;max-width:800px}.notice{padding:12px 14px;border-radius:10px;background:#38302155;border:1px solid #69552e;color:#efd39f;font-size:12px;margin-bottom:16px}.filters{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin:15px 0}.filters input,.filters select{width:100%;min-width:0;background:#0c101b;border:1px solid #354058;border-radius:9px;color:var(--text);padding:11px 9px;font-size:12px}.filters input::placeholder{color:#677990}.wide{grid-column:span 2}.btnrow{display:flex;gap:8px;flex-wrap:wrap}.mini{border-radius:8px;background:#1c2535;border:1px solid #344054;color:var(--muted);font-size:11px;padding:7px 11px}.mini.active{background:#493a70;border-color:#a18bdf;color:white}.items{display:flex;flex-direction:column;gap:9px}.item{border:1px solid var(--edge);background:var(--panel);border-radius:13px;padding:14px;text-align:left;color:var(--text);width:100%}.item:hover{background:#1a2231;border-color:#7166a5}.item-top{display:flex;align-items:center;justify-content:space-between;gap:8px}.item strong{font-size:14px}.item-meta{display:flex;flex-wrap:wrap;gap:7px;margin-top:8px;font-size:11px;color:var(--muted)}.evidence-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}.proof{background:#0d1320;border:1px solid var(--edge);border-radius:10px;padding:10px;min-height:78px}.proof .dot{width:7px;height:7px;border-radius:50%;display:inline-block;background:#687587;margin-right:4px}.proof.verified .dot{background:var(--green)}.proof.inferred .dot{background:var(--amber)}.proof.blocked .dot{background:var(--red)}.proof .plabel{color:var(--muted);font-size:11px}.proof .status{font-size:12px;font-weight:800;margin-top:7px}.matrix{width:100%;border-collapse:collapse;font-size:12px;min-width:650px}.matrix td,.matrix th{border-bottom:1px solid var(--edge);text-align:left;padding:10px 8px}.matrix th{color:var(--muted);font-weight:700}.scrollx{overflow-x:auto}.audit{position:relative;padding-left:17px;border-left:1px solid #445069;margin-left:6px}.audititem{position:relative;margin-bottom:13px}.audititem::before{content:'';width:9px;height:9px;border:2px solid var(--violet);border-radius:50%;position:absolute;left:-24px;top:4px;background:var(--bg)}.drawerback{position:fixed;z-index:50;inset:0;background:#0009;display:none}.drawerback.open{display:block}.drawer{position:absolute;right:0;top:0;bottom:0;width:min(600px,100%);background:#111725;box-shadow:-15px 0 50px #0009;overflow:auto;padding:24px}.close{position:sticky;float:right;top:0;background:#303a52;color:white;border:0;border-radius:10px;padding:8px 12px}.drawer h2{font-size:23px;line-height:1.2;margin:16px 0 8px}.field{padding:11px 0;border-bottom:1px solid var(--edge)}.field b{display:block;font-size:11px;color:var(--muted);margin-bottom:4px}.field a{word-break:break-all}.list{margin:0;padding-left:19px}.list li{margin-bottom:9px}.hidden{display:none!important}.placeholder{border:1px dashed #53617a;padding:20px;border-radius:13px;color:var(--muted);text-align:center}.bottom{display:none}.statrow{display:flex;gap:7px;flex-wrap:wrap}.statrow .tag{font-size:10px}.divider{border-top:1px solid var(--edge);margin:17px 0}.flex{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.callout{background:#18202f;border:1px solid #33435a;padding:11px;border-radius:10px;margin-top:12px;font-size:12px}.count{font-weight:800;color:var(--violet)}\n@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}.filters{grid-template-columns:repeat(3,1fr)}.evidence-grid{grid-template-columns:repeat(3,1fr)}}\n@media(max-width:600px){.shell{padding:0 12px 93px}.header{padding:11px 0;margin-bottom:13px}.headerin{padding:0 12px}.logo{height:33px;width:33px}.name{font-size:17px}.right .pill{display:none}.pagehead h1{font-size:24px}.tabs{display:none}.bottom{display:grid;grid-template-columns:repeat(5,1fr);position:fixed;bottom:0;left:0;right:0;z-index:20;background:#0d1220ed;backdrop-filter:blur(15px);border-top:1px solid #354054;padding:8px 4px calc(8px + env(safe-area-inset-bottom))}.bottom button{font-size:10px;font-weight:700;color:var(--muted);background:none;border:0;padding:4px 0}.bottom button.active{color:var(--violet)}.bottom .sym{font-size:18px;display:block}.filters{grid-template-columns:repeat(2,minmax(0,1fr))}.wide{grid-column:span 2}.filters input,.filters select{font-size:12px}.kpi{padding:12px;min-height:100px}.kpi .val{font-size:21px}.evidence-grid{grid-template-columns:repeat(2,1fr)}.card{padding:13px}.drawer{padding:15px}.pagehead{align-items:center}.pagehead .tiny{display:none}}\n\n/* Plain-language decision dashboard */\n.hero-intro{margin-bottom:16px;padding:16px 18px;border:1px solid #453e68;border-radius:14px;background:linear-gradient(115deg,#28203c,#151c2d 72%);}\n.hero-intro .hero-heading{font-size:19px;line-height:1.35;font-weight:790;letter-spacing:-.4px;margin:5px 0 7px;}\n.hero-intro p{margin:0;color:#bac6d6;font-size:13px;max-width:880px}\n.answergrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n.answercard{background:linear-gradient(135deg,#171e2d,#101520);border:1px solid #344055;border-radius:15px;padding:16px;display:flex;flex-direction:column;gap:10px;min-height:183px}\n.answer-top{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}\n.answer-top h2{font-size:17px;line-height:1.24;margin:0}\n.answercard .short-answer{font-size:17px;line-height:1.2;font-weight:850;letter-spacing:-.35px}\n.answercard .detail{font-size:12px;color:#b0bed0;line-height:1.55;flex:1;margin:0}\n.answercard .answerlink{font-size:12px;color:var(--cyan);text-align:left;align-self:flex-start;border:0;background:none;padding:3px 0;font-weight:750}\n.answercard .answerlink:hover{text-decoration:underline}\n.answercard .label{font-size:10px;color:var(--muted);font-weight:800;text-transform:uppercase;letter-spacing:1px}\n.answercard.caution{border-color:#6b5235}\n.answercard.proofmissing{border-color:#554b72}\n.answercard.knownissue{border-color:#754553}\n.today{margin-top:14px;background:#151e29;border:1px solid #395767;border-radius:14px;padding:15px}\n.today h2{font-size:16px;margin:0 0 9px}\n.nextsteps{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}\n.nextstep{border:1px solid #334254;border-radius:10px;background:#0e1520;padding:11px;font-size:12px;color:#b9c8d9}\n.nextstep b{display:block;font-size:12px;color:#f1f6ff;margin-bottom:5px}\n.nextstep .stepno{color:var(--cyan);font-weight:850;margin-right:4px}\n.footnote{font-size:11px;color:var(--muted);margin-top:10px}\n.deeper{margin-top:16px;border-radius:13px;border:1px solid #354156;background:#121827;padding:3px 13px}\n.deeper>summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:10px;justify-content:space-between;padding:13px 2px;color:#d5dfed;font-weight:800}\n.deeper>summary::-webkit-details-marker{display:none}\n.deeper>summary:after{content:'⌄';font-size:18px;color:var(--violet)}\n.deeper[open]>summary:after{content:'⌃'}\n.deeper .inner{padding:0 0 16px}\n@media(max-width:700px){.answergrid,.nextsteps{grid-template-columns:1fr}.answercard{min-height:auto;padding:14px}.hero-intro{padding:14px}.hero-intro .hero-heading{font-size:17px}.today{padding:14px}.nextstep{padding:10px}.deeper{padding:2px 10px}}\n\n\n/* Evidence Board v2: beginner-first visuals, honest uncertainty, touch-first. */\n.v2-lede{border:1px solid #394267;background:linear-gradient(120deg,#211b38,#111a2b 75%);border-radius:17px;padding:18px;margin:4px 0 16px}\n.v2-lede h2{font-size:23px;line-height:1.18;margin:4px 0 8px;letter-spacing:-.6px}\n.v2-lede p{font-size:13px;color:#b5c4d6;margin:0;max-width:870px}\n.v2-kicker{text-transform:uppercase;letter-spacing:1.7px;color:#b1a0ff;font-weight:800;font-size:10px}\n.v2-stamp{display:inline-block;color:#e4c17b;font-size:11px;margin-top:11px;padding:5px 9px;background:#3a2a2066;border:1px solid #775830;border-radius:7px}\n.v2-insights{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n.v2-insight{border:1px solid #34415b;border-radius:15px;background:#151e2d;padding:15px;text-align:left;color:#eef3fc;display:flex;flex-direction:column;gap:7px;min-width:0;min-height:180px}\n.v2-insight:hover{border-color:#8272be;background:#20283a}\n.v2-insight .caption{font-size:11px;color:#9facbf;font-weight:750}\n.v2-insight .value{font-size:22px;line-height:1.12;font-weight:850;letter-spacing:-.5px}\n.v2-insight .help{font-size:12px;color:#b0bdd0;flex:1}\n.v2-insight .drill{font-size:11px;color:#94dfee;font-weight:800}\n.v2-section{margin-top:20px}\n.v2-section h2{font-size:18px;letter-spacing:-.3px;margin:0 0 5px}\n.v2-section .small{font-size:12px;color:#9cabc0;margin:0 0 11px}\n.v2-panel{border:1px solid #344158;background:#111824;border-radius:14px;padding:16px}\n.v2-legend{display:flex;flex-wrap:wrap;gap:12px;color:#aabbce;font-size:11px}\n.v2-dot{display:inline-block;height:9px;width:9px;border-radius:2px;margin-right:4px;vertical-align:middle}\n.v2-road{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n.v2-stage{padding:12px;border-radius:10px;border:1px solid #303f53;background:#0d1320;min-width:0}\n.v2-stage h3{font-size:12px;color:#d8e3f0;margin:0 0 7px;line-height:1.3}\n.v2-stage .num{font-size:23px;font-weight:850;line-height:1.2}\n.v2-stage .expl{font-size:11px;color:#9facbf;min-height:32px}\n.v2-meter{height:8px;border-radius:99px;background:#303b51;margin:11px 0;overflow:hidden}\n.v2-meter>span{display:block;height:100%;border-radius:99px;background:#80cead}\n.v2-meter.warn>span{background:#e4ad68}\n.v2-meter.unknown{background:repeating-linear-gradient(90deg,#293348,#293348 9px,#20283a 9px,#20283a 17px)}\n.v2-meter.unknown>span{display:none}\n.v2-summary{background:#1a2333;border:1px solid #3c4f6b;padding:12px 14px;border-radius:12px;margin-top:13px;font-size:12px;line-height:1.6}\n.v2-graphs{display:grid;grid-template-columns:1.6fr 1fr;gap:12px}\n.v2-chart{min-width:0;overflow:hidden}\n.v2-chart .scroll{width:100%;overflow-x:auto;scrollbar-width:thin}\n.v2-chart svg{min-width:720px;display:block}\n.v2-workflows{display:flex;gap:5px;align-items:end;overflow-x:auto;padding:16px 3px 8px;min-height:135px}\n.v2-run{width:38px;min-width:38px;border:0;background:transparent;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;padding:4px;color:#93a6bc;font-size:10px;gap:7px}\n.v2-run:hover{background:#29344a;border-radius:8px}\n.v2-bar{display:block;width:24px;border-radius:5px 5px 2px 2px}\n.v2-run[data-status=\"success\"] .v2-bar{background:#80cba9}\n.v2-run[data-status=\"failure\"] .v2-bar{background:#f18799}\n.v2-run[data-status=\"cancelled\"] .v2-bar{background:#9ca3b9}\n.v2-run[data-status=\"active\"] .v2-bar{background:#b19cff}\n.v2-line{height:1px;background:#2c3b52;margin:6px 0 12px}\n.v2-matrix{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n.v2-asset{padding:12px;border:1px solid #34415b;background:#131a28;border-radius:12px}\n.v2-asset>strong{font-size:13px}\n.v2-horizons{display:flex;gap:6px;margin-top:9px}\n.v2-cell{flex:1;min-width:0;border:1px solid #69424b;background:#3e2733;color:#ffd0d7;border-radius:8px;padding:9px 5px;font-size:12px;font-weight:800}\n.v2-cell.good{border-color:#327462;background:#1a423b;color:#a8f4d5}\n.v2-cell.unknown{border-color:#4b5367;background:#212a3a;color:#aebcd1}\n.v2-cell:focus-visible,.v2-insight:focus-visible{outline:3px solid #bea9ff;outline-offset:2px}\n.v2-callout{background:#182a2c;border:1px solid #335c60;border-radius:12px;padding:14px;font-size:12px}\n.v2-callout strong{color:#d7f6ed}\n.v2-next{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}\n.v2-next>div{background:#131c2c;border:1px solid #304259;border-radius:11px;padding:13px;font-size:12px;color:#aebcd0}\n.v2-next b{display:block;color:#e6eef7;margin-bottom:5px}\n.v2-faq{margin-top:14px}\n.v2-faq details{padding:11px 13px;background:#131c29;border:1px solid #314156;border-radius:9px;margin:7px 0}\n.v2-faq summary{cursor:pointer;font-size:13px;font-weight:750}\n.v2-faq p{font-size:12px;color:#bac7d7;margin:9px 0 0}\n.v2-mini-action{background:transparent;color:#92dce7;border:0;text-align:left;font-weight:800;padding:7px 0;font-size:12px}\n.v2-mini-action:hover{text-decoration:underline}\n.v2-date{font-size:11px;color:#d7b978;padding-top:8px}\n.v2-empty{border:1px dashed #47566e;border-radius:10px;padding:21px;text-align:center;color:#afc0d4;font-size:12px;min-height:100px}\n.v2-detail-note{border:1px solid #405471;background:#182238;border-radius:10px;padding:12px;color:#c5d3e4;font-size:12px;margin-top:12px}\n.v2-chip{display:inline-block;font-size:10px;font-weight:850;color:#e7c385;background:#2b2531;border:1px solid #62503c;padding:4px 8px;border-radius:99px}\n@media(max-width:1100px){.v2-insights{grid-template-columns:repeat(2,minmax(0,1fr))}.v2-road{grid-template-columns:repeat(2,minmax(0,1fr))}.v2-graphs{grid-template-columns:1fr}}\n@media(max-width:600px){.v2-lede{padding:15px}.v2-lede h2{font-size:20px}.v2-insights{grid-template-columns:repeat(2,minmax(0,1fr))}.v2-insight{padding:12px;min-height:167px}.v2-insight .value{font-size:19px}.v2-insight .help{font-size:11px}.v2-road{grid-template-columns:repeat(2,minmax(0,1fr))}.v2-stage{padding:11px}.v2-matrix{grid-template-columns:repeat(2,minmax(0,1fr))}.v2-next{grid-template-columns:1fr}.v2-panel{padding:12px}.v2-section h2{font-size:16px}}\n\n\n.v2-score-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-top:12px}\n.v2-score{background:#0e1623;border:1px solid #33415a;border-radius:10px;padding:12px;min-width:0}\n.v2-score-label{font-size:11px;margin-top:10px;color:#c5d2e2}\n.v2-score-track{height:10px;border-radius:8px;background:#30394b;overflow:hidden;margin:4px 0 6px}\n.v2-score-track span{display:block;height:100%;border-radius:8px}\n@media(max-width:1050px){.v2-score-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:560px){.v2-score-grid{grid-template-columns:1fr}}\n\n.tz-label{font-size:11px;display:flex;align-items:center;gap:7px;color:var(--muted)}.tz-label select{font-size:11px;border:1px solid #33425a;border-radius:8px;color:#eef3fc;background:#142033;padding:7px 5px;max-width:100px}@media(max-width:480px){.tz-label{font-size:0;gap:0}}\n#banner.sync-panel{border:1px solid #45768c;background:linear-gradient(135deg,#0c2633,#15172c);color:#e3f4fd;padding:15px;border-radius:15px;box-shadow:inset 0 1px 0 #ffffff12}\n.sync-head{display:flex;align-items:center;justify-content:space-between;gap:9px;flex-wrap:wrap;margin-bottom:12px}\n.sync-label{font-weight:850;letter-spacing:1px;font-size:11px;color:#91def0}\n.sync-label.warn{color:#edbd7b}.sync-label.bad{color:#ff9caa}\n.sync-version{border:1px solid #6a5a8d;background:#30234878;border-radius:20px;padding:4px 8px;color:#dbc8ff;font-size:10px;font-weight:850}\n.sync-metrics{display:grid;grid-template-columns:1fr 1fr;gap:9px}\n.sync-metrics>div{min-width:0;border:1px solid #37536d;background:#091522ac;padding:11px;border-radius:10px}\n.sync-meta{display:block;color:#96b8ce;font-size:10px;font-weight:850;letter-spacing:.9px}\n.sync-metrics strong{font-size:15px;display:block;margin:5px 0;line-height:1.35;overflow-wrap:anywhere}\n.sync-metrics small{display:block;font-size:11px;color:#acc6d7;line-height:1.4}\n.sync-explain{margin-top:11px;color:#b1cddd;font-size:11px;line-height:1.5}\n@media(max-width:390px){.sync-metrics{grid-template-columns:1fr}.sync-head{align-items:flex-start}}\n</style></head><body>\n<header class=\"header\"><div class=\"headerin\"><div class=\"brand\"><div class=\"logo\">R</div><div><div class=\"name\">RivaL <span style=\"color:var(--violet)\">Evidence</span></div><div class=\"sub\">XMarket · Intelligence · signed auto-updates</div></div></div><div class=\"right\"><span id=\"fresh\" class=\"pill pending\">● Checking sources</span><label class=\"tz-label\">Time zone <select aria-label=\"Display time zone\" id=\"time-zone\" onchange=\"selectTz(this.value)\"><option value=\"device\">My device</option><option value=\"America/New_York\">Eastern</option></select></label><button class=\"action\" onclick=\"refresh()\" aria-label=\"Check saved evidence\">↻ <span style=\"font-size:11px\">Check</span></button></div></div></header>\n<main class=\"shell\"><div id=\"banner\" class=\"notice sync-panel\">Status labels are dated observations, not current failures. Read the timestamp and source before acting.</div>\n<div class=\"pagehead\"><div><div class=\"eyebrow\">Research integrity / read-only</div><h1 id=\"page-title\">RivaL at a glance</h1><div id=\"updated\" class=\"tiny muted\">Loading repository evidence…</div></div><span class=\"tag pending\">NO WRITE ACTIONS</span></div>\n<nav class=\"tabs\" id=\"tabs\"></nav>\n<div id=\"content\"></div></main><nav class=\"bottom\" id=\"bottom\"></nav>\n<div class=\"drawerback\" id=\"drawerback\" onclick=\"closeDrawer(event)\"><aside class=\"drawer\" id=\"drawer\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Evidence detail\"></aside></div>\n<script>window.onerror=function(m,s,l,c,e){document.body.dataset.pageerror=String(m)+' @'+l+':'+c;};</script><script>\n'use strict';\nvar repoBase='https://github.com/UglyGameFace/';var tracked=[\n{n:529,f:'XMarket',title:'Native-history XMarket challenger',severity:'critical',desc:'Polymarket/Kalshi native price + exchange disagreement versus perp direction. Historical match remains unproven.',asset:'BTC ETH SOL XRP',horizon:'5 15 60',market:'Polymarket Kalshi Perpetual'},\n{n:531,f:'XMarket',title:'Polymarket native sample parser',severity:'high',desc:'Collapse identical adjacent price samples while rejecting conflicting duplicates.',market:'Polymarket',asset:'BTC ETH SOL XRP',horizon:'15'},\n{n:533,f:'XMarket',title:'Historical overlap recovery & diagnostics',severity:'critical',desc:'Expose absent paired native bars and HTTP import failure cause without treating healthy live feeds as history.',market:'Polymarket Kalshi',asset:'BTC ETH SOL XRP',horizon:'5 15 60'},\n{n:534,f:'XMarket',title:'One-time post-export training',severity:'high',desc:'Workflow scheduled for Nov 13, 10:17 AM Eastern; proof requires an actual run and usable artifacts.',market:'Polymarket Kalshi',asset:'BTC ETH SOL XRP',horizon:'5 15 60'},\n{n:536,f:'Online learning',title:'Forward collector latency & weight receipts',severity:'high',desc:'Reduce healthy-venue delays and distinguish actual persisted weight updates from routine heartbeats.',market:'Perpetual',asset:'BTC ETH SOL XRP',horizon:'5 15 60'},\n{n:526,f:'VolCal',title:'VolCal per-asset shadow challenger',severity:'high',desc:'Calibrated logistic models with volatility, compression and reversal features; shadow-only.',market:'Perpetual',asset:'BTC ETH SOL XRP',horizon:'5 15 60'},\n{n:538,f:'VolCal',title:'24h / 7d / 30d volatility ablations',severity:'medium',desc:'Research-only comparison of volatility blending and independent move/timing outputs.',market:'Perpetual',asset:'BTC ETH SOL XRP',horizon:'5 15 60'},\n{n:532,f:'Model Lab',title:'Human-readable model experiment labels',severity:'low',desc:'Saved Lab genomes displayed with meaningful signal composition rather than opaque hashes.',market:'Perpetual',asset:'BTC ETH SOL XRP',horizon:'5 15 60'},\n{n:463,f:'Regime',title:'Trending-only regime v2 trial',severity:'medium',desc:'Offline trending-subset logistic and shadow-only gates.',market:'Perpetual',asset:'BTC ETH SOL XRP',horizon:'5 15 60'},\n{n:447,f:'GBM',title:'GBM v2 challenger & pinned fitting',severity:'medium',desc:'Portable LightGBM family with pinned evidence and shadow-only issuance.',market:'Perpetual',asset:'BTC ETH SOL XRP',horizon:'5 15 60'}\n];var NAV=['Overview','Experiments','CI queue','Evidence','Audit'];var state={page:'Overview',view:'All',filters:{q:'',project:'',family:'',market:'',asset:'',horizon:'',workflow:'',run:'',severity:'',status:'',date:''},prs:[],runs:[],intPrs:[],snap:'',source:'loading',error:'',detail:null};\nvar fallback={447:'a6aa459922470608ba5a65cba570c7e3b0c35951',463:'d36e5e116a8a94bbed3d1c75a874db307546b90f',529:'09fb01e13d7fd19449707935242b17114acc7467',531:'c577d5a5d2959e0c7ff3df1eeafef8cc24ad41ca',533:'9c824e6ca856d42547ba8dd7e10dea2de62e2fbe',534:'b70a53b138e65c5ec312c6fe891177b68a4296c5',536:'00122267b943abd5283feb2b42563475a56f4368',526:'67e43813f36a3bd817bbbf99f5c7ca0cb66b6632',532:'ece3265a027e6c7ce3116cc571fb0ea24bd2aeff',538:'304880b78567d9384ac56a41e07b7c5209697fbf'};\nfunction esc(x){return String(x==null?'':x).replace(/[&<>\"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]})}\nfunction siteTz(){try{var p=localStorage.getItem('rival-display-zone');return p==='device'?(Intl.DateTimeFormat().resolvedOptions().timeZone||'America/New_York'):'America/New_York'}catch(e){return 'America/New_York'}}\nfunction selectTz(value){try{localStorage.setItem('rival-display-zone',value==='America/New_York'?'America/New_York':'device')}catch(e){}render()}\nfunction date(x){if(!x)return 'Unknown';var d=new Date(x);if(!Number.isFinite(d.getTime()))return 'Unknown';return new Intl.DateTimeFormat('en-US',{timeZone:siteTz(),month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(d)}\nfunction ageOf(x){var d=Date.parse(x||'');return Number.isFinite(d)?Date.now()-d:Infinity}\nfunction sourceAgeText(x){var m=ageOf(x);if(!Number.isFinite(m))return 'unknown age';if(m<0)return 'clock mismatch';if(m<60000)return 'under 1 min old';if(m<3600000)return Math.floor(m/60000)+' min old';return Math.floor(m/3600000)+'h '+Math.floor((m%3600000)/60000)+'m old'}\nfunction sourceCurrent(){var e=state.evidence;return !!(e&&e.provenance&&e.provenance.method==='github-actions-oidc'&&e.provenance.verified===true&&ageOf(e.captured_at)>=0&&ageOf(e.captured_at)<25*60*1000)}\nfunction sourceBanner(){\n var e=state.evidence;\n var signed=!!(e&&e.provenance&&e.provenance.method==='github-actions-oidc'&&e.provenance.verified===true);\n var recent=signed&&sourceCurrent();\n var title=recent?'SIGNED SNAPSHOT • RECENT':signed?'SIGNED SNAPSHOT • DELAYED':'VERIFIED SOURCE UNAVAILABLE';\n var checkStatus=state.receiptError?'Last check failed':state.receiptCheckedAt?'Checked '+date(state.receiptCheckedAt):'Checking saved evidence…';\n var capture=e&&e.captured_at?date(e.captured_at):'Not available';\n var age=e&&e.captured_at?sourceAgeText(e.captured_at):'Age unknown';\n var label=recent?'ok':signed?'warn':'bad';\n return '<div class=\"sync-head\"><span class=\"sync-label '+label+'\">'+esc(title)+'</span><span class=\"sync-version\">AUTO-SYNC BOARD v2.1</span></div>'\n +'<div class=\"sync-metrics\"><div><span class=\"sync-meta\">LAST VERIFIED SOURCE</span><strong>'+esc(capture)+'</strong><small>'+esc(age)+'</small></div>'\n +'<div><span class=\"sync-meta\">YOUR BROWSER CHECK</span><strong>'+esc(checkStatus)+'</strong><small>Auto-checks every 60 sec while open</small></div></div>'\n +'<div class=\"sync-explain\"><b>Signed snapshots, not a live stream.</b> GitHub collects production evidence separately. Refresh checks the latest saved receipt, never a live Discloud command.</div>';\n}\nfunction link(url,label){return url?'<a href=\"'+esc(url)+'\" target=\"_blank\" rel=\"noopener noreferrer\">'+esc(label)+'</a>':'Unknown'}\nfunction tag(s,cl){return '<span class=\"tag '+(cl||'')+'\">'+esc(s)+'</span>'}\nfunction take(){var p=new URLSearchParams(location.search);state.page=NAV.includes(p.get('tab'))?p.get('tab'):'Overview';Object.keys(state.filters).forEach(function(k){state.filters[k]=p.get(k)||''})}\nfunction sync(){var p=new URLSearchParams();p.set('tab',state.page);Object.keys(state.filters).forEach(function(k){if(state.filters[k])p.set(k,state.filters[k])});history.replaceState(null,'','?'+p.toString())}\nfunction setPage(p){state.page=p;sync();render();scrollTo({top:0,behavior:'smooth'})}\nfunction filter(k,val){var active=document.activeElement,lab=active&&active.getAttribute?active.getAttribute('aria-label'):null,pos=0;try{pos=active.selectionStart||0}catch(e){}state.filters[k]=val;sync();render();if(lab&&['q','workflow','run'].includes(k)){var list=document.querySelectorAll('#content input');for(var i=0;i<list.length;i++){if(list[i].getAttribute('aria-label')===lab){list[i].focus();try{list[i].setSelectionRange(pos,pos)}catch(e){}break}}}}\nfunction refresh(){state.source='loading';document.getElementById('fresh').textContent='● Checking saved GitHub evidence';fetch('/api/bootstrap',{cache:'no-store'}).then(function(r){if(!r.ok)throw Error('GitHub snapshot HTTP '+r.status);return r.json()}).then(function(j){if(j.source!=='github-snapshot'||!j.rival||!Array.isArray(j.rival.prs))throw Error((j.errors||[]).join('; ')||'GitHub evidence unavailable');state.prs=j.rival.prs;state.runs=j.rival.runs||[];state.intPrs=[];state.snap=j.fetched_at;state.error='';state.source='snapshot';render()}).catch(function(e){state.error=e.message;state.source='offline';render()})}\nfunction prs(){var items=state.prs.map(function(p){var t=tracked.find(function(x){return x.n===p.number}),title=p.title||'Untitled PR',s=title.toLowerCase(),f=t?t.f:/xmarket|polymarket|kalshi|archive|prospective|native.history/.test(s)?'XMarket':/volcal|volatil/.test(s)?'VolCal':/model.lab|genome/.test(s)?'Model Lab':/regime/.test(s)?'Regime':/gbm/.test(s)?'GBM':/online.learn|weight|forward.audit/.test(s)?'Online learning':/llm|intelligence|lfm3/.test(s)?'Intelligence':/evidence.board|signed.receipt/.test(s)?'Evidence Board':'Infrastructure';return {n:p.number,f:f,title:title,desc:t?t.desc:'Actual GitHub PR; runtime/experiment proof is independently checked.',merged:!!p.merged_at,stage:p.merged_at?'merged':p.state||'unverified',commit:p.merge_commit_sha||'',head:p.head_sha||'',at:p.merged_at||p.updated_at||'',project:'RivaL',repo:'RivaL',severity:t?t.severity:'unrated',asset:t&&t.asset||'',horizon:t&&t.horizon||'',market:t&&t.market||'Unspecified',url:p.html_url,raw:p}});return items.concat(state.intPrs.map(function(p){return {n:p.number,f:'Intelligence',title:p.title,desc:'Signed GitHub record; live inference requires separate evidence.',merged:!!p.merged_at,stage:p.merged_at?'merged':p.state,commit:p.merge_commit_sha||'',head:p.head_sha||'',at:p.merged_at||p.updated_at||'',project:'RivaL Intelligence',repo:'RivaL-Intelligence',severity:'unrated',asset:'',horizon:'',market:'Unspecified',url:p.html_url,raw:p}})).sort(function(a,b){return String(b.at).localeCompare(String(a.at))})}\nfunction pass(t){var f=state.filters;var hay=[t.title,t.n,t.f,t.desc,t.commit].join(' ').toLowerCase();if(f.q&&!hay.includes(f.q.toLowerCase()))return false;if(f.project&&t.project!==f.project)return false;if(f.family&&t.f!==f.family)return false;if(f.market&&!String(t.market).toLowerCase().includes(f.market.toLowerCase()))return false;if(f.asset&&!String(t.asset).includes(f.asset))return false;if(f.horizon&&!String(t.horizon).split(' ').includes(f.horizon))return false;if(f.severity&&t.severity!==f.severity)return false;if(f.status&&t.stage!==f.status)return false;if((f.workflow||f.run)&&!state.runs.some(function(r){return r.head_sha===t.commit&&(!f.workflow||String(r.name||'').toLowerCase().includes(f.workflow.toLowerCase()))&&(!f.run||String(r.id).includes(f.run))}))return false;if(f.date&&(!t.at||t.at.slice(0,10)<f.date))return false;return true}\nfunction sel(k,options){return '<select aria-label=\"'+esc(k)+'\" onchange=\"filter(\\''+k+'\\',this.value)\"><option value=\"\">'+esc(k[0].toUpperCase()+k.slice(1))+' · All</option>'+options.map(function(o){return '<option value=\"'+esc(o)+'\" '+(state.filters[k]===o?'selected':'')+'>'+esc(o)+'</option>'}).join('')+'</select>'}\nfunction filters(){var f=state.filters;return '<div class=\"filters\"><input class=\"wide\" placeholder=\"Search PR, model, SHA...\" aria-label=\"Search\" value=\"'+esc(f.q)+'\" oninput=\"filter(\\'q\\',this.value)\">'+sel('project',['RivaL','RivaL Intelligence'])+sel('family',['XMarket','VolCal','Model Lab','Regime','GBM','Online learning','Intelligence'])+sel('market',['Perpetual','Polymarket','Kalshi'])+sel('asset',['BTC','ETH','SOL','XRP'])+sel('horizon',['5','15','60'])+sel('severity',['critical','high','medium','low'])+sel('status',['merged','open','closed','unverified','success','failure','cancelled','skipped','queued','in_progress'])+'<input type=\"date\" title=\"From date\" aria-label=\"From date\" value=\"'+esc(f.date)+'\" onchange=\"filter(\\'date\\',this.value)\"><input placeholder=\"Workflow name\" aria-label=\"Workflow\" value=\"'+esc(f.workflow)+'\" oninput=\"filter(\\'workflow\\',this.value)\"><input placeholder=\"Run ID\" aria-label=\"Run ID\" value=\"'+esc(f.run)+'\" oninput=\"filter(\\'run\\',this.value)\"><button class=\"action\" onclick=\"resetFilters()\">Clear filters</button></div>'}\nfunction resetFilters(){Object.keys(state.filters).forEach(function(k){state.filters[k]=''});sync();render()}\nfunction rows(){var all=prs(),a=all.filter(pass);return a.length?a.map(function(t){return '<button class=\"item\" onclick=\"openExperiment(\\''+esc(t.repo)+'\\','+t.n+')\"><div class=\"item-top\"><strong>'+esc(t.title)+'</strong>'+tag(t.stage.toUpperCase(),t.merged?'ok':'pending')+'</div><div class=\"summary\">'+esc(t.f)+' · '+esc(t.project)+'</div><div class=\"item-meta\"><span>PR #'+t.n+'</span><span>'+date(t.at)+'</span><span>Live effects require separate proof</span></div></button>'}).join(''):'<div class=\"v2-empty\">No matching changes in '+all.length+' signed PR records. <button class=\"action\" onclick=\"resetFilters()\">Clear filters</button></div>'}\nfunction proof(label,status,sub){return '<div class=\"proof '+(status==='VERIFIED'?'verified':status==='REPORTED'?'inferred':status==='BLOCKED'?'blocked':'')+'\"><div class=\"plabel\">'+label+'</div><div class=\"status\"><span class=\"dot\"></span>'+status+'</div><div class=\"tiny muted\">'+sub+'</div></div>'}\nfunction proofGrid(){return '<div class=\"evidence-grid\">'+proof('Historical overlap','REPORTED','Prior run: 0 pairs')+proof('Native fidelity','UNKNOWN','Live ≠ history')+proof('Eligible fit','UNKNOWN','No proof receipt')+proof('Drive publication','UNKNOWN','Not connected')+proof('Host import','UNKNOWN','Not connected')+proof('Issued shadow','REPORTED','0 at prior host receipt')+'</div>'}\nfunction kpi(k,v,d){return '<div class=\"kpi\"><div class=\"label\">'+k+'</div><div class=\"val\">'+v+'</div><div class=\"tiny muted\">'+d+'</div></div>'}\nfunction overview(){var active=state.runs.filter(function(r){return ['queued','in_progress','waiting','pending'].includes(r.status)});return '<div class=\"grid\">'+kpi('Tracked changes',String(tracked.length),'RivaL tracked PRs')+kpi('Pending workflows',String(active.length),state.source==='live'?'From fetched latest runs':'Last-known/unavailable')+kpi('Eligible XMarket fits','?', 'No verified latest fit receipt')+kpi('Promotable scopes','?', 'No verified after-cost edge')+'</div><div class=\"section\"><div class=\"secthead\"><h2>Evidence required before model claims</h2>'+tag('snapshot vs actual proof','warn')+'</div>'+proofGrid()+'<div class=\"callout\">Historical run '+link('https://github.com/UglyGameFace/RivaL/actions/runs/43224850573','#43224850573')+' generated four archive artifacts, while PR '+link(repoBase+'RivaL/pull/533','#533')+' reports zero matched native history bars. This is a time-stamped secondary finding, not a fresh host receipt.</div></div><div class=\"section\"><div class=\"secthead\"><h2>Work queues</h2><span class=\"tiny muted\">Tap to inspect</span></div><div class=\"btnrow\" id=\"viewbuttons\"></div><div id=\"viewlist\"></div></div><div class=\"section\"><div class=\"secthead\"><h2>12 XMarket asset / horizon scopes</h2>'+tag('UNVERIFIED RUNTIME','warn')+'</div>'+matrix()+'</div>'}\nfunction matrix(){var s='<div class=\"card scrollx\"><table class=\"matrix\"><thead><tr><th>Asset</th><th>Horizon</th><th>Overlap</th><th>Fidelity</th><th>Fit</th><th>Drive</th><th>Shadow</th><th>After-cost</th></tr></thead><tbody>';['BTC','ETH','SOL','XRP'].forEach(function(a){[5,15,60].forEach(function(h){s+='<tr><td><b>'+a+'</b></td><td>'+h+'m</td><td>'+tag('Unproven','warn')+'</td><td>'+tag('Unknown')+'</td><td>'+tag('Unknown')+'</td><td>'+tag('Unknown')+'</td><td>'+tag('Unknown')+'</td><td>'+tag('Unknown')+'</td></tr>'})});return s+'</tbody></table></div>'}\nfunction updateView(v){state.view=v;render()}\nfunction workQueues(){var names=['All','Pending CI','Merged · host unverified','Missing artifacts','Cold start','Shadow results','Promotion gates','Claims'],buttons=names.map(function(n){return '<button class=\"mini '+(n===state.view?'active':'')+'\" onclick=\"updateView(\\''+n+'\\')\">'+n+'</button>'}).join(''),all=prs(),runs=state.runs,proof=state.evidence||{},host=proof.host||{},db=proof.database||{},drive=proof.drive||{},reports=drive.reports||[],live=runs.filter(function(x){return ['queued','in_progress','pending','waiting'].includes(x.status)}),content='';\n if(state.view==='All')content='<div class=\"v2-detail-note\">'+all.length+' real PRs · '+runs.length+' workflow runs from signed GitHub snapshot '+date(state.snap)+'.</div><div class=\"items\">'+rows()+'</div>';\n else if(state.view==='Pending CI')content='<div class=\"v2-detail-note\">'+live.length+' pending/running jobs in this snapshot. If none, here are recent completed jobs instead.</div><div class=\"items\">'+(live.length?live:runs.slice(0,6)).map(runItem).join('')+'</div>';\n else if(state.view==='Merged · host unverified')content='<div class=\"v2-detail-note\">A PR merge proves code history, not a running Discloud feature. '+all.filter(function(x){return x.merged}).length+' merges in snapshot.</div><div class=\"items\">'+all.filter(function(x){return x.merged}).slice(0,25).map(function(t){return '<button class=\"item\" onclick=\"openExperiment(\\''+esc(t.repo)+'\\','+t.n+')\"><b>'+esc(t.title)+'</b><div class=\"tiny muted\">#'+t.n+' · '+date(t.at)+'</div></button>'}).join('')+'</div>';\n else if(state.view==='Missing artifacts')content='<div class=\"v2-detail-note\">'+reports.length+' actual Drive training reports from '+date(drive.latest_report_at)+'. Model artifact hashes and exact host-import hashes are not in this receipt.</div><div class=\"items\">'+reports.map(function(r){return '<button class=\"item\" onclick=\"v2scope(\\''+esc(r.asset)+'\\','+Number(r.horizon)+')\"><b>'+esc(r.asset)+' · '+r.horizon+'m</b> '+tag(r.status,r.status==='blocked'?'bad':'pending')+'<div class=\"tiny muted\">'+esc(r.reason||'Unknown')+' · '+date(r.report_modified_at)+'</div></button>'}).join('')+'</div>';\n else if(state.view==='Cold start')content='<div class=\"v2-detail-note\">At '+date(proof.captured_at)+': '+esc(host.xmarket_fresh_inputs)+'/'+esc(host.xmarket_expected_inputs)+' live feeds; '+reports.filter(function(r){return !r.gate_passed}).length+'/'+reports.length+' dated training reports still gated; '+esc(host.xmarket_imported_scopes)+' imported models and '+esc(host.xmarket_shadow_rows)+' XMarket shadow rows. Next: source export → native time match → gated fit → signed artifact → host import → future outcomes. '+link('https://github.com/UglyGameFace/RivaL/actions/workflows/archive-model-training.yml','Training workflow')+'</div>';\n else if(state.view==='Shadow results'){var scores=proof.performance&&proof.performance.scopes||[];content='<div class=\"v2-detail-note\">XMarket shadow rows at last host check: '+esc(host.xmarket_shadow_rows)+'. The '+scores.length+' paired scores below belong to other model research, not trained XMarket models or after-cost proof.</div><div class=\"items\">'+scores.map(function(x){return '<div class=\"item\"><b>'+esc(x.asset)+' '+x.horizon+'m</b> · '+x.paired_outcomes+' settled pairs<div class=\"tiny muted\">Model Brier '+Number(x.model_brier).toFixed(3)+' vs baseline '+Number(x.baseline_brier).toFixed(3)+' · no qualified edge</div></div>'}).join('')+'</div>'}\n else if(state.view==='Promotion gates')content='<div class=\"v2-detail-note\">'+esc(db.qualified_paper_scopes)+'/'+esc(db.evaluated_paper_scopes)+' qualified paper scopes at last host check. Requirements: ≥150 future outcomes, ≥21 days, ≥80% quote coverage, after-cost baseline superiority and statistically reliable results. '+link('https://github.com/UglyGameFace/RivaL/issues/299','Tracked model evidence work')+'</div>';\n else content='<div class=\"v2-detail-note\"><b>Verified:</b> '+all.length+' recent PRs, '+runs.length+' GitHub runs, '+reports.length+' Drive reports, signed host and database checks.<div class=\"divider\"></div><b>Observed but not model improvement:</b> '+esc(db.weight_updates_observed)+' changing-weight streams, '+esc(host.xmarket_shadow_rows)+' XMarket shadows.<div class=\"divider\"></div><b>Still unverified:</b> exact model file and import hashes, paired eligible XMarket history, cost-adjusted forward advantage.</div>';\n return {buttons:buttons,content:content};}\nfunction runItem(r){return '<button class=\"item\" onclick=\"openRun('+r.id+')\"><div class=\"item-top\"><strong>'+esc(r.name)+'</strong>'+tag(r.conclusion||r.status,r.conclusion==='success'?'ok':r.conclusion==='failure'?'bad':'pending')+'</div><div class=\"item-meta\"><span>#'+r.id+'</span><span>'+date(r.created_at)+'</span><span>SHA '+esc((r.head_sha||'').slice(0,8))+'</span></div></button>'}\nfunction ciPage(){var a=state.runs.filter(function(r){var f=state.filters;return (!f.run||String(r.id).includes(f.run))&&(!f.workflow||String(r.name||'').toLowerCase().includes(f.workflow.toLowerCase()))&&(!f.date||String(r.created_at||'').slice(0,10)>=f.date)&&(!f.status||r.status===f.status||r.conclusion===f.status)});var pending=a.filter(function(r){return ['queued','waiting','pending','in_progress'].includes(r.status)}).length,fail=a.filter(function(r){return ['failure','cancelled'].includes(r.conclusion)}).length;return '<section class=\"v2-lede\"><div class=\"v2-kicker\">Signed GitHub Actions</div><h2>Real workflows, not a schedule drawing</h2><p>'+state.runs.length+' latest runs checked '+date(state.snap)+'. '+pending+' pending, '+fail+' failed/cancelled among matching runs.</p></section>'+filters()+'<div class=\"section\"><h2>Workflow runs</h2><div class=\"items\">'+(a.length?a.slice(0,45).map(runItem).join(''):'<div class=\"v2-empty\">Nothing matches these filters. <button class=\"action\" onclick=\"resetFilters()\">Show all runs</button></div>')+'</div></div><div class=\"v2-detail-note\">A scheduled training or release only exists after the run actually starts. '+link('https://github.com/UglyGameFace/RivaL/actions/workflows/archive-model-training.yml','Inspect archive training')+'</div>'}\nfunction evidencePage(){return '<div class=\"section\"><div class=\"secthead\"><h2>Source credibility</h2></div>'+proofGrid()+'</div><div class=\"section\"><div class=\"two\"><div class=\"card\"><h2>Known archive evidence</h2><p>Workflow '+link('https://github.com/UglyGameFace/RivaL/actions/runs/43224850573','#43224850573')+' completed its four asset jobs, with archived report files observed for BTC, ETH, SOL and XRP.</p><p>PR '+link(repoBase+'RivaL/pull/533','#533')+' documents 0 matched Polymarket and Kalshi native feature bars in that run. <b>A successful job or archive file is not a trained XMarket model.</b></p>'+tag('SECONDARY SOURCE','warn')+'</div><div class=\"card\"><h2>Unavailable private evidence</h2><ul class=\"list\"><li>Discloud host SHA / active configuration</li><li>Postgres fitted model and forward audit receipts</li><li>Private Google Drive publish/import hashes</li><li>Private Sentry runtime and error details</li><li>RivaL Intelligence live inference evidence</li></ul>'+tag('NOT CONNECTED','pending')+'</div></div></div><div class=\"section\"><h2>Asset × timeframe proof matrix</h2>'+matrix()+'</div>'}\nfunction auditPage(){var a=prs().filter(pass),d=state.evidence||{},r=d.drive&&d.drive.reports||[],merged=a.filter(function(t){return t.merged}).length;return '<section class=\"v2-lede\"><div class=\"v2-kicker\">Signed source audit</div><h2>Actual repository change history</h2><p>'+a.length+' matching PRs, '+merged+' merged. Historical Drive evidence: '+r.length+' scope reports. These are not claims about live deployment or profit.</p></section>'+filters()+'<div class=\"section\"><div class=\"items\">'+(a.length?a.map(function(t){return '<button class=\"item\" onclick=\"openExperiment(\\''+esc(t.repo)+'\\','+t.n+')\"><div class=\"item-top\"><strong>'+esc(t.title)+'</strong>'+tag(t.stage,t.merged?'ok':'pending')+'</div><div class=\"item-meta\"><span>#'+t.n+'</span><span>'+date(t.at)+'</span><span>'+esc(t.f)+'</span></div></button>'}).join(''):'<div class=\"v2-empty\">No matching records in this bounded snapshot. <button class=\"action\" onclick=\"resetFilters()\">Clear filters</button></div>')+'</div></div><div class=\"v2-detail-note\">Provenance: '+(d.provenance&&d.provenance.source_url?link(d.provenance.source_url,'Signed collector run'):'not connected')+'. Missing future model proof stays explicitly unknown.</div>'}\nfunction experimentsSourcePanel(){\n var d=state.evidence||{},h=d.host||{},db=d.database||{},items=v2rows(),perf=d.performance&&d.performance.scopes||[];\n var blocked=items.filter(function(x){return x.training_status==='blocked'}).length;\n var s='<section class=\"v2-section\"><div class=\"v2-panel\"><div class=\"secthead\"><h2>Real model evidence, separate from code PRs</h2>'+tag('SIGNED SOURCE-DATED','ok')+'</div><p class=\"small\">PRs below describe changes to code. The evidence here describes model research. Neither means a model is deployed or profitable.</p><div class=\"v2-road\">'+\n v2stage('Training reports',items.length,12,'Actual XMarket asset/timeframe reports','','drive')+\n v2stage('Blocked fits',blocked,items.length||12,'Dated reports, not permanent state','','fit')+\n v2stage('Paired score scopes',perf.length,null,'Settled research models, not after-cost edge','','quality')+\n v2stage('XMarket host imports',h.xmarket_imported_scopes,12,'Last host read '+date(d.captured_at),'','drive')+'</div>'+\n '<div class=\"v2-detail-note\">Score receipts cover '+perf.length+' asset/timeframe research scopes. Model Lab genome inventory, exact artifact hashes and real inference-quality outcomes are <b>not connected</b> to this public source; an empty model-family filter must not be treated as a dead model. '+link('https://github.com/UglyGameFace/RivaL/issues/299','Research proof requirements')+'</div>'+\n '<h3>Per-asset training evidence</h3>'+v2matrix()+\n '<div class=\"v2-section\"><h3>Observed paired scoring scopes</h3>'+(perf.length?'<div class=\"items\">'+perf.slice(0,8).map(function(x){return '<div class=\"item\"><b>'+esc(x.asset)+' '+esc(x.horizon)+'m</b> · '+esc(x.paired_outcomes)+' settled pairs<div class=\"tiny muted\">Brier model '+Number(x.model_brier).toFixed(3)+' vs matched baseline '+Number(x.baseline_brier).toFixed(3)+' · after-cost qualification not proven</div></div>'}).join('')+'</div>':'<div class=\"v2-empty\">No paired-score receipt. This does not mean training activity is zero.</div>')+'</div></div></section>';\n return s;\n}\nfunction render(){var p=state.page;document.getElementById('page-title').textContent=p==='Overview'?'RivaL at a glance':p;document.getElementById('fresh').textContent=state.evidence&&state.evidence.provenance?'● '+(sourceCurrent()?'Recent signed snapshot':'Saved snapshot')+' · '+sourceAgeText(state.evidence.captured_at):'● Evidence unavailable';document.getElementById('fresh').className='pill '+(sourceCurrent()?'ok':'warn');document.getElementById('updated').textContent='GitHub saved '+(state.snap?date(state.snap):'unavailable')+' · Private receipt '+(state.evidence&&state.evidence.captured_at?date(state.evidence.captured_at):'unavailable')+' · Displayed in '+(siteTz()==='America/New_York'?'Eastern time ('+new Intl.DateTimeFormat('en-US',{timeZone:siteTz(),timeZoneName:'short'}).formatToParts(new Date()).find(function(p){return p.type==='timeZoneName'}).value+')':'Device time');var zoneElement=document.getElementById('time-zone');if(zoneElement){var z='America/New_York';try{z=localStorage.getItem('rival-display-zone')==='device'?'device':'America/New_York'}catch(e){}zoneElement.value=z;}document.getElementById('tabs').innerHTML=NAV.map(function(x){return '<button class=\"tab '+(x===p?'active':'')+'\" onclick=\"setPage(\\''+x+'\\')\">'+x+'</button>'}).join('');document.getElementById('bottom').innerHTML=NAV.map(function(x,i){return '<button class=\"'+(x===p?'active':'')+'\" onclick=\"setPage(\\''+x+'\\')\"><span class=\"sym\">'+['▦','◈','⏱','◇','≡'][i]+'</span>'+x+'</button>'}).join('');var content=p==='Overview'?overview():p==='Experiments'?filters()+'<div class=\"section\"><div class=\"secthead\"><h2>Experiments <span class=\"count\">'+prs().filter(pass).length+'</span></h2>'+tag('read only')+'</div><div class=\"items\">'+rows()+'</div></div>':p==='CI queue'?ciPage():p==='Evidence'?evidencePage():auditPage();document.getElementById('content').innerHTML=content;if(p==='Experiments'){document.getElementById('content').insertAdjacentHTML('afterbegin',experimentsSourcePanel())}if(p==='Overview'){var q=workQueues();document.getElementById('viewbuttons').innerHTML=q.buttons;document.getElementById('viewlist').innerHTML='<div class=\"section\" style=\"margin-top:13px\">'+q.content+'</div>'}document.getElementById('banner').innerHTML=sourceBanner()+(state.error?' GitHub snapshot refresh error: '+esc(state.error):'')}\nfunction closeDrawer(e){if(!e||e.target===document.getElementById('drawerback')){document.getElementById('drawerback').classList.remove('open');document.body.style.overflow=''}}\nfunction show(html){document.getElementById('drawer').innerHTML='<button class=\"close\" onclick=\"closeDrawer()\">Close ✕</button>'+html;document.getElementById('drawerback').classList.add('open');document.body.style.overflow='hidden'}\nfunction field(name,value){return '<div class=\"field\"><b>'+esc(name)+'</b>'+value+'</div>'}\nfunction openExperiment(repo,n){var t=prs().find(function(x){return x.n===n&&x.repo===repo});if(!t)return;var runs=state.runs.filter(function(r){return r.head_sha&&[t.head,t.commit].includes(r.head_sha)});show('<div class=\"eyebrow\">'+esc(t.project)+' · '+esc(t.f)+'</div><h2>'+esc(t.title)+'</h2><div class=\"statrow\">'+tag(t.stage.toUpperCase(),t.merged?'ok':'pending')+tag('Host uptake unverified','warn')+'</div>'+field('Verified PR',link(t.url||repoBase+t.repo+'/pull/'+n,'Open #'+n))+field('Merge SHA',t.commit?link(repoBase+t.repo+'/commit/'+t.commit,t.commit):'No merge recorded')+field('Last update',date(t.at))+field('Same-commit CI evidence',runs.length?runs.map(function(r){return '<div>'+tag(r.conclusion||r.status,r.conclusion==='success'?'ok':'warn')+' '+link(r.html_url,r.name+' #'+r.id)+'</div>'}).join(''):'No same-commit run in the bounded signed window. Open the PR checks.')+field('Related private Drive reports','Training reports are asset/timeframe records, not proof this PR published or imported a model')+field('Production / model quality','Exact active SHA, cost-adjusted forward improvement and inference quality require independent receipts')+'<div class=\"v2-detail-note\">Do not infer a deployed feature or profitable model from a merged PR.</div>')}\nfunction openRun(id){var r=state.runs.find(function(x){return x.id===id});if(!r)return;show('<div class=\"eyebrow\">GitHub Actions · read-only</div><h2>'+esc(r.name)+'</h2><div class=\"statrow\">'+tag(r.conclusion||r.status,r.conclusion==='failure'?'bad':r.conclusion==='success'?'ok':'pending')+tag('GitHub verified','ok')+'</div>'+field('Workflow run',link(r.html_url,'Open run #'+r.id))+field('Started',date(r.created_at))+field('Source SHA',r.head_sha?link(repoBase+'RivaL/commit/'+r.head_sha,r.head_sha):'Unknown')+field('Jobs, failed steps & artifacts','<div id=\"runinfo\">Checking specific run evidence…</div>')+field('Deployment truth','A successful pipeline does not establish live host deployment or model uptake. Verify an independent runtime receipt.')+'<div class=\"callout\">Next safe diagnostic: inspect the failed job step and artifacts for this run, then reconcile against host receipt.</div>');fetch('/api/run?id='+id).then(function(res){if(!res.ok)throw Error('HTTP '+res.status);return res.json()}).then(function(j){var info=document.getElementById('runinfo');if(!info)return;if(j.source==='cached-run-metadata'){info.innerHTML='<div class=\"v2-detail-note\"><b>Run status verified in the cached GitHub snapshot.</b> Detailed job steps, logs, and artifact downloads are not mirrored. '+link(r.html_url,'Open the official GitHub run')+' to inspect them. Unretrieved is not the same as missing.</div>';return}var jobs=j.jobs||[],a=j.artifacts||[];info.innerHTML=(j.errors&&j.errors.length?'<div class=\"tiny muted\">'+esc(j.errors.join('; '))+'</div>':'')+ '<div><b>Jobs ('+jobs.length+')</b></div>'+jobs.map(function(x){var fail=(x.steps||[]).filter(function(s){return s.conclusion==='failure'});return '<div class=\"field\">'+esc(x.name)+' '+tag(x.conclusion||x.status,x.conclusion==='failure'?'bad':x.conclusion==='success'?'ok':'pending')+(fail.length?'<div class=\"tiny\">Failed step: '+esc(fail.map(function(z){return z.name}).join(', '))+'</div>':'')+'<div class=\"tiny\">'+link(x.html_url,'Inspect job/logs')+'</div></div>'}).join('')+'<div style=\"margin-top:14px\"><b>Artifacts ('+a.length+')</b></div>'+a.map(function(x){return '<div class=\"field\">'+esc(x.name)+' · '+Math.round((x.size_in_bytes||0)/1024)+' KiB '+tag(x.expired?'Expired':'Exists',x.expired?'warn':'ok')+'</div>'}).join('')+'<div class=\"tiny muted\">Returned GitHub API window. Empty may be legitimate or a pagination/permissions limit; it is not proof an artifact never existed.</div>'}).catch(function(e){var info=document.getElementById('runinfo');if(info)info.textContent='Unable to verify run jobs/artifacts: '+e.message})}\n\n/* Human-readable summary; detailed tools stay under an expandable section. */\nfunction openPanel(v){\n  state.page='Overview';state.view=v;sync();render();\n  var d=document.getElementById('techdetails');\n  if(d){d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'})}\n}\nfunction overview(){\n  var ghAvailable=state.source==='live'||state.source==='partial';\n  var pending=state.runs.filter(function(r){return ['queued','in_progress','waiting','pending'].includes(r.status)});\n  var pendingLabel=ghAvailable&&state.runs.length?String(pending.length):'Unknown';\n  var stamped='Prior XMarket receipt, Nov 12 10:51 AM Eastern';\n  return '<div class=\"hero-intro\"><div class=\"eyebrow\">Your RivaL research scorecard</div><div class=\"hero-heading\">Is RivaL working, learning, and actually getting better?</div><p>This board checks the evidence behind your experiments. It does <b>not</b> make trades, train models or deploy changes. Missing proof is not the same as failure.</p></div>'+\n  '<div class=\"answergrid\">'+\n  '<section class=\"answercard proofmissing\"><div class=\"answer-top\"><div><div class=\"label\">01 / System health</div><h2>Is RivaL running?</h2></div>'+tag('NOT VERIFIED','warn')+'</div><div class=\"short-answer\">We cannot confirm live health.</div><p class=\"detail\">GitHub release history is visible, but this board has no Discloud runtime connection. A successful deployment workflow cannot prove the bot is up right now.</p><button class=\"answerlink\" onclick=\"setPage(\\'CI queue\\')\">Inspect GitHub workflows →</button></section>'+\n  '<section class=\"answercard proofmissing\"><div class=\"answer-top\"><div><div class=\"label\">02 / Learning</div><h2>Is RivaL learning?</h2></div>'+tag('XMARKET UNPROVEN','warn')+'</div><div class=\"short-answer\">XMarket learning is not proven.</div><p class=\"detail\">A Nov 12 host receipt reported <b>0 fitted XMarket models and 0 shadow rows</b>. That is a dated report about XMarket, <b>not</b> evidence that every RivaL model stopped learning.</p><button class=\"answerlink\" onclick=\"openPanel(\\'Shadow results\\')\">See what would prove learning →</button></section>'+\n  '<section class=\"answercard proofmissing\"><div class=\"answer-top\"><div><div class=\"label\">03 / Prediction quality</div><h2>Is RivaL improving?</h2></div>'+tag('NOT PROVEN','warn')+'</div><div class=\"short-answer\">No verified edge yet.</div><p class=\"detail\">We need future settled predictions compared fairly with the existing model and market price, with costs and statistical uncertainty included. Green CI is not predictive performance.</p><button class=\"answerlink\" onclick=\"openPanel(\\'Promotion gates\\')\">View performance requirements →</button></section>'+\n  '<section class=\"answercard knownissue\"><div class=\"answer-top\"><div><div class=\"label\">04 / Blockers</div><h2>What needs fixing?</h2></div>'+tag('PRIOR ISSUE','bad')+'</div><div class=\"short-answer\">Historical overlap is the clearest blocker.</div><p class=\"detail\">The previously inspected four-asset XMarket archive produced artifacts, but its reports showed <b>0 matched native price/feature bars</b>. Later fixes were merged; fresh re-test evidence is needed.</p><button class=\"answerlink\" onclick=\"openPanel(\\'Cold start\\')\">See why it matters →</button></section>'+\n  '</div>'+\n  '<section class=\"today\"><div class=\"eyebrow\">What should happen next</div><h2>Prove the pipeline in order, before promoting XMarket</h2><div class=\"nextsteps\">'+\n  '<div class=\"nextstep\"><b><span class=\"stepno\">1.</span>Check the next training run</b>Inspect whether the Nov 13 scheduled run really fired, not merely whether it was configured.</div>'+\n  '<div class=\"nextstep\"><b><span class=\"stepno\">2.</span>Check the model evidence</b>Look for real matched historical bars, eligible fitted models, Drive publication and confirmed host import.</div>'+\n  '<div class=\"nextstep\"><b><span class=\"stepno\">3.</span>Check real predictions</b>Require issued and settled shadow rows, then an after-cost comparison against the incumbent.</div>'+\n  '</div><div class=\"footnote\">Read-only source: '+link('https://github.com/UglyGameFace/RivaL/pull/533','XMarket history investigation #533')+' · '+link('https://github.com/UglyGameFace/RivaL/pull/534','Scheduled training #534')+'. GitHub source state: '+esc(state.source)+'. Current live bot state: unknown.</div></section>'+\n  '<details id=\"techdetails\" class=\"deeper\"><summary><span>Show the engineering evidence and all 12 market scopes</span><span class=\"tiny muted\">Detailed research</span></summary><div class=\"inner\">'+\n  '<div class=\"section\"><div class=\"secthead\"><h2>Six things to prove</h2>'+tag('UNKNOWN ≠ ZERO','pending')+'</div>'+proofGrid()+'<div class=\"callout\">A prior archive '+link('https://github.com/UglyGameFace/RivaL/actions/runs/43224850573','#43224850573')+' had four downloadable asset artifacts. The '+link('https://github.com/UglyGameFace/RivaL/pull/533','follow-up investigation')+' reported no matched native history. New runs can supersede that old finding; verify each run separately.</div></div>'+\n  '<div class=\"section\" id=\"workqueue\"><div class=\"secthead\"><h2>Research work queues</h2>'+tag('READ ONLY','ok')+'</div><div class=\"btnrow\" id=\"viewbuttons\"></div><div id=\"viewlist\"></div></div>'+\n  '<div class=\"section\"><div class=\"secthead\"><h2>12 asset / timeframe proof scopes</h2>'+tag('HOST NOT CONNECTED','warn')+'</div>'+matrix()+'</div>'+\n  '</div></details>';\n}\n\n\nstate.evidence=null;\nfunction readEvidence(){\n  return fetch('/api/source-evidence',{cache:'no-store'})\n    .then(function(r){if(!r.ok)throw Error('Receipt HTTP '+r.status);return r.json()})\n    .then(function(d){state.evidence=d&&d.provenance?d:null;state.receiptCheckedAt=new Date().toISOString();state.receiptError='';render()})\n    .catch(function(){state.receiptCheckedAt=new Date().toISOString();state.receiptError='Evidence cache temporarily unavailable';render()});\n}\nvar beforeSourceRefresh=refresh;\nrefresh=function(){beforeSourceRefresh();readEvidence()};\nfunction verificationAge(d){\n  var s=d&&d.captured_at?Date.parse(d.captured_at):NaN;\n  if(!Number.isFinite(s))return 'Time unknown';\n  return date(d.captured_at)+' · '+sourceAgeText(d.captured_at)+' · saved signed evidence, not a live stream';\n}\nfunction sourcePanel(){\n  var d=state.evidence;\n  if(!d||!d.provenance)return '<div class=\"notice\">Discloud, PostgreSQL and private Drive evidence are not available through this session. The public site never receives their credentials.</div>';\n  var h=d.host||{},db=d.database||{},dr=d.drive||{},age=verificationAge(d);\n  var src=d.provenance.source_url||'';\n  var l='<div class=\"section\" style=\"margin-top:0\"><div class=\"secthead\"><h2>Verified source receipts</h2>'+tag(d.provenance.method==='github-actions-oidc'?'SIGNED AUTOMATIC':'VERIFIED SNAPSHOT','ok')+'</div>';\n  l+='<div class=\"grid\" style=\"grid-template-columns:repeat(auto-fit,minmax(150px,1fr))\">'+\n    kpi('Discloud cycles',h.status==='verified'?'Fresh at check':'Unverified',esc(h.forecast_status||'Unknown')+' forecast · '+esc(h.learning_status||'Unknown')+' learning')+\n    kpi('PostgreSQL learning',db.status==='verified_read'?(db.weight_updates_observed!=null?String(db.weight_updates_observed)+' streams':'Read verified'):'Unavailable','Weight versions changed, not proof of profit')+\n    kpi('XMarket imports',h.xmarket_imported_scopes===null?'Unknown':String(h.xmarket_imported_scopes||0)+' scopes','Host-side evidence at last check')+\n    kpi('Drive training reports',dr.reports_considered===null?'Unknown':String(dr.reports_considered||0)+' scopes','Private report bytes inspected; latest: '+date(dr.latest_report_at))+\n  '</div><div class=\"callout\">Source timing: '+esc(age)+'. Verified by '+link(src,'Discloud / database workflow receipt')+' and private Drive reports. No credentials or private file contents are exposed here.</div></div>';\n  return l;\n}\nvar _overviewWithDetails=overview;\noverview=function(){\n var h=state.evidence&&state.evidence.host||{},db=state.evidence&&state.evidence.database||{},d=state.evidence&&state.evidence.drive||{};\n var output=_overviewWithDetails();\n if(h.status==='verified'){\n   output=output.replace('We cannot confirm live health.','Verified healthy at last check.');\n   output=output.replace('GitHub release history is visible, but this board has no Discloud runtime connection. A successful deployment workflow cannot prove the bot is up right now.',\n   'An authenticated Discloud check confirmed fresh forecast and learning cycles at '+date(state.evidence.captured_at)+'. This is a point-in-time result, not a guarantee it is still healthy.');\n }\n if(db.status==='verified_read'){\n   output=output.replace('XMarket learning is not proven.','Online weight learning is proven.');\n   output=output.replace('A Nov 12 host receipt reported <b>0 fitted XMarket models and 0 shadow rows</b>. That is a dated report about XMarket, <b>not</b> evidence that every RivaL model stopped learning.',\n   'PostgreSQL lineage showed '+esc(db.weight_updates_observed)+' model streams changed weights. XMarket still had '+esc(h.xmarket_imported_scopes)+' imported fits and '+esc(h.xmarket_shadow_rows)+' shadow rows at the same check. Learning and prediction quality are different questions.');\n }\n if(db.qualified_paper_scopes===0)output=output.replace('No verified edge yet.','No qualified edge in this receipt.');\n if(d.status==='verified_reports')output=output.replace('Historical overlap is the clearest blocker.','XMarket still lacks eligible overlap.');\n return sourcePanel()+output;\n}\nvar previousEvidencePage=evidencePage;\nevidencePage=function(){\n var d=state.evidence, h=d&&d.host||{},db=d&&d.database||{},dr=d&&d.drive||{};\n var reports=(dr.reports||[]);\n var details='';\n if(d&&reports.length){\n   details='<div class=\"section\"><h2>Private Drive report inspection · 12 scopes</h2><div class=\"card scrollx\"><table class=\"matrix\"><thead><tr><th>Asset</th><th>Horizon</th><th>Training</th><th>PM overlap</th><th>Kalshi overlap</th><th>Gate</th><th>Reason</th></tr></thead><tbody>'+\n     reports.map(function(r){return '<tr><td>'+esc(r.asset)+'</td><td>'+esc(r.horizon)+'m</td><td>'+tag(r.status,r.status==='blocked'?'bad':'')+'</td><td>'+esc(r.pm_pairs==null?'Unknown':String(r.pm_pairs))+'</td><td>'+esc(r.kalshi_pairs==null?'Unknown':String(r.kalshi_pairs))+'</td><td>'+esc(r.gate_passed?'Passed':'Not passed')+'</td><td>'+esc(r.reason||'Unknown')+'</td></tr>'}).join('')+\n   '</tbody></table></div><div class=\"footnote\">The numbers are from reports dated '+date(dr.latest_report_at)+'. A blocked historical report does not prove subsequent runs are blocked.</div></div>';\n }\n return sourcePanel()+details+previousEvidencePage();\n};\n\n\n/* v2 novice-facing, evidence-graded visual presentation. All metrics are sourced,\n   and historical points never become a fake performance time series. */\nstate.training=null;\nvar previousVisualRefresh=refresh;\nrefresh=function(){previousVisualRefresh();loadTrainingEvidence()};\nfunction loadTrainingEvidence(){\n fetch('/api/training-snapshot',{cache:'no-store'})\n .then(function(r){if(!r.ok)throw Error('historical report unavailable');return r.json()})\n .then(function(d){state.training=d&&Array.isArray(d.reports)?d:null;render()})\n .catch(function(){state.training=null;render()});\n}\nfunction v2stamp(v){return v?date(v):'No timestamp'}\nfunction v2receipt(){return state.evidence&&state.evidence.provenance?state.evidence:null}\nfunction v2rows(){\n var archived=state.training&&Array.isArray(state.training.reports)?state.training.reports:[];\n var drive=state.evidence&&state.evidence.drive;\n var sourceDate=state.training&&state.training.verified_at;\n var useSigned=drive&&drive.status==='verified_reports'&&Array.isArray(drive.reports)&&drive.reports.length>0&&drive.latest_report_at&&(!sourceDate||Date.parse(drive.latest_report_at)>Date.parse(sourceDate));\n if(!useSigned)return archived.map(function(r){return Object.assign({},r,{evidence_date:sourceDate,source:'historical-snapshot'})});\n return drive.reports.map(function(r){return {asset:r.asset,horizon:r.horizon,training_status:r.status,gate_passed:r.gate_passed===true,pm_status:r.pm_status,kalshi_status:r.kalshi_status,pm_pairs:r.pm_pairs,kalshi_pairs:r.kalshi_pairs,eligible_rows:r.eligible_rows,reason:r.reason,pm_history_bars:null,kalshi_history_bars:null,evidence_date:r.report_modified_at||drive.latest_report_at,source:'signed-drive-receipt'}});\n}\nfunction v2line(label,value,body,word){\n return '<button class=\"v2-insight\" onclick=\"v2info(\\''+word+'\\')\"><span class=\"caption\">'+label+'</span><span class=\"value\">'+value+'</span><span class=\"help\">'+body+'</span><span class=\"drill\">Understand this →</span></button>';\n}\nfunction v2info(key){\n var defs={\n health:['Is the bot healthy?','A working GitHub workflow is not enough. The host must show recent forecast and learning receipts from the production database. The current board has a genuine receipt but cannot assume it stays healthy after its timestamp.','Inspect the newest signed Discloud receipt and check that its timestamp is recent and both cycles say fresh.'],\n learning:['Is RivaL learning?','A changed weight means a model updated its parameters. This is evidence of learning activity, but it is not evidence that predictions got more accurate. XMarket is a separate challenger that had no imported models in the last available host receipt.','Compare actual stored weight versions, then compare the model against its previous baseline on future, settled outcomes.'],\n quality:['Is RivaL improving?','Improvement needs future settled predictions, market-price and incumbent-model baselines, enough observations, and costs. A model can learn continuously and still never beat the market.','Inspect paired forward outcomes, calibration, after-cost comparisons and adjusted uncertainty; do not promote because a workflow passed.'],\n blocker:['What blocks XMarket?','The November 12 reports include candidate historical bars, but no matching prospective/live feature bars. Without independently matched rows, the training gate correctly refuses an eligible model. A Kalshi 429 is a retryable backfill rate-limit error.','Verify a newer completed-day export and a fresh training run; check joined bars and matched contract timestamps before retrying model fitness.'],\n overlap:['Historical overlap','Matching the exact market, contract and feature time across two independently observed sources. Having lots of historical rows alone does not establish trustworthy overlap.','Look for positive paired_points, overlap coverage and provider-specific fidelity evidence in a newer XMarket report.'],\n fit:['Eligible fit','A trained model that passes history, leakage, fidelity and evaluation gates. A JSON report saying blocked is not an eligible fitted model.','Inspect a training report with gates_passed=true and its corresponding independently validated model file.'],\n drive:['Drive publication / import','A training report on Drive proves the report exists. Model publication means a vetted model artifact was actually uploaded; import is a separate confirmation that Discloud loaded that exact artifact hash.','Read the model publish receipt, then match its hash against the database-backed active model inventory.'],\n shadow:['Shadow predictions','Research-only forecasts saved before the outcome is known. The last host receipt counted zero XMarket shadow rows, not zero predictions from every RivaL model.','Confirm persisted issued rows, timestamped outcomes and correct source/model lineage before scoring.'],\n rate:['Kalshi HTTP 429','Kalshi throttled a historical backfill request. That is a temporary request-rate problem, not proof that historical data is permanently unavailable. The same error appears in multiple reports and must not be counted as 12 separate incidents.','Check paced retries and newer completed backfill receipts, including rate-limit response metadata.'],\n all:['How to read this board','Green means a specific verified observation at a specific time. Amber means a report, stale check or incomplete evidence. Gray means unknown. Red means a documented failed gate for a particular run. This is NOT a live trading control panel.','Use the Date/Source labels and open the supporting GitHub run before deciding an issue is still present.']\n };\n var x=defs[key]||defs.all;show('<div class=\"eyebrow\">Explained simply</div><h2>'+esc(x[0])+'</h2><p>'+esc(x[1])+'</p><div class=\"v2-detail-note\"><b>Safest next check</b><p>'+esc(x[2])+'</p></div><div class=\"v2-detail-note\"><b>Research rule</b><p>Past report evidence is a historical observation, not a prediction of what the system is doing now. Reading this board does not trigger training or trading.</p></div>');\n}\nfunction v2chartBar(n,max){return Math.max(0,Math.min(100,Math.round(100*(n||0)/max)))}\nfunction v2stage(label,n,den,detail,grade,key){\n var known=Number.isFinite(n),str=known?String(n)+(den?'/'+den:''):'Unknown';\n var cl=!known?'unknown':n===0?'warn':'';\n return '<div class=\"v2-stage\"><h3>'+label+' <button class=\"v2-mini-action\" aria-label=\"What is '+label+'?\" onclick=\"v2info(\\''+key+'\\')\">ⓘ</button></h3><div class=\"num\">'+str+'</div><div class=\"v2-meter '+cl+'\"><span style=\"width:'+(known&&den?v2chartBar(n,den):known&&n>0?100:0)+'%\"></span></div><div class=\"expl\">'+esc(detail)+'</div></div>';\n}\nfunction v2pipeline(){\n var r=v2receipt(),h=r&&r.host||{},db=r&&r.database||{},ds=v2rows();\n var known=ds.length===12;\n var scopeSource=ds.length&&ds[0].source==='signed-drive-receipt'?'Signed Drive reports':'Nov 12 archived reports';\n var eligible=known?ds.filter(function(x){return x.training_status==='fitted'&&x.gate_passed}).length:null;\n var matched=known?ds.filter(function(x){return (x.pm_pairs||0)>0&&(x.kalshi_pairs||0)>0}).length:null;\n return '<div class=\"v2-road\">'+\n v2stage('Market feeds observed',h.xmarket_fresh_inputs,8,'Last host check · live inputs','observed','overlap')+\n v2stage('Historical reports inspected',known?12:null,12,scopeSource+' · reports, not models','observed','drive')+\n v2stage('Matched historical scopes',matched,12,scopeSource+' · both providers paired','blocked','overlap')+\n v2stage('Eligible model fits',eligible,12,'In the inspected report set','blocked','fit')+\n v2stage('Model artifacts published',null,12,'File hashes not independently verified','unknown','drive')+\n v2stage('Models imported on host',h.xmarket_imported_scopes,12,'Last host check · not live now','reported','drive')+\n v2stage('Issued XMarket shadow rows',h.xmarket_shadow_rows,null,'Last host check · past 24h','reported','shadow')+\n v2stage('Paper scopes qualified',db.qualified_paper_scopes,db.evaluated_paper_scopes,'Last host check · not live profits','reported','quality')+\n '</div>';\n}\nfunction v2historyGraph(){\n var a=state.training&&Array.isArray(state.training.reports)?state.training.reports:[];if(a.length===0)return '<div class=\"v2-empty\">A verified per-scope history chart is not available. No example numbers have been invented.</div>';\n a=a.slice().sort(function(x,y){return ['BTC','ETH','SOL','XRP'].indexOf(x.asset)-['BTC','ETH','SOL','XRP'].indexOf(y.asset)||x.horizon-y.horizon});\n var max=Math.max(1,...a.map(function(x){return Math.max(x.pm_history_bars||0,x.kalshi_history_bars||0)})),W=900,H=276,base=219,top=20,scale=(base-top)/(Math.ceil(max/50)*50);\n var svg='<svg viewBox=\"0 0 '+W+' '+H+'\" width=\"900\" height=\"276\" role=\"img\" aria-label=\"Verified November 12 historical candidate bars, Polymarket and Kalshi, 12 asset horizon scopes. These are NOT matched training samples.\">';\n for(var tick=0;tick<=Math.ceil(max/50)*50;tick+=50){\n var y=base-tick*scale;\n svg+='<line x1=\"42\" y1=\"'+y.toFixed(1)+'\" x2=\"887\" y2=\"'+y.toFixed(1)+'\" stroke=\"#2d394d\" stroke-width=\"1\"/><text x=\"37\" y=\"'+(y+4).toFixed(1)+'\" text-anchor=\"end\" font-size=\"11\" fill=\"#94a6bb\">'+tick+'</text>';\n }\n a.forEach(function(x,i){var g=56+i*69,ph=(x.pm_history_bars||0)*scale,kh=(x.kalshi_history_bars||0)*scale;svg+='<g onclick=\"v2scope(\\''+x.asset+'\\','+x.horizon+')\" style=\"cursor:pointer\"><title>'+x.asset+' '+x.horizon+'m: '+x.pm_history_bars+' PM candidate history bars, '+x.kalshi_history_bars+' Kalshi candidate history bars, 0 matching live bars in the historical reports</title><rect x=\"'+(g+4)+'\" y=\"'+(base-ph).toFixed(1)+'\" width=\"21\" height=\"'+ph.toFixed(1)+'\" rx=\"3\" fill=\"#6ed7df\"/><rect x=\"'+(g+27)+'\" y=\"'+(base-kh).toFixed(1)+'\" width=\"21\" height=\"'+kh.toFixed(1)+'\" rx=\"3\" fill=\"#aa91ef\"/><text text-anchor=\"middle\" x=\"'+(g+26)+'\" y=\"239\" font-size=\"11\" fill=\"#e2ebfa\">'+x.horizon+'m</text></g>'});\n ['BTC','ETH','SOL','XRP'].forEach(function(asset,i){svg+='<text x=\"'+(56+i*207+94)+'\" y=\"260\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"700\" fill=\"#b4c5db\">'+asset+'</text>'});\n svg+='</svg>';return '<div class=\"scroll\">'+svg+'</div>';\n}\nfunction v2workflowGraph(){\n var rows=state.runs.slice().filter(function(r){return /CI|XMarket|Archive|Release|receipt|model/i.test(r.name||'')}).sort(function(a,b){return String(a.created_at).localeCompare(String(b.created_at))}).slice(-16);\n if(!rows.length)return '<div class=\"v2-empty\">Workflow data unavailable. No run history to plot.</div>';\n return '<div class=\"v2-workflows\">'+rows.map(function(x){\n var kind=x.status==='in_progress'||x.status==='queued'?'active':x.conclusion||'active',ht=kind==='success'?76:kind==='failure'?90:kind==='cancelled'?45:55;\n if(kind==='skipped'||kind==='cancelled')kind='cancelled';else if(kind==='timed_out'||kind==='action_required')kind='failure';else if(!['success','failure','active'].includes(kind))kind='active';\n return '<button class=\"v2-run\" data-status=\"'+kind+'\" onclick=\"openRun('+x.id+')\" title=\"'+esc(x.name)+' · '+esc(x.conclusion||x.status)+' · '+esc(date(x.created_at))+'\"><span class=\"v2-bar\" style=\"height:'+ht+'px\"></span><span>'+date(x.created_at).replace(/^.*?, /,'')+'h</span></button>';\n }).join('')+'</div><div class=\"v2-legend\"><span><i class=\"v2-dot\" style=\"background:#80cba9\"></i>Passed</span><span><i class=\"v2-dot\" style=\"background:#f18799\"></i>Failed</span><span><i class=\"v2-dot\" style=\"background:#9ca3b9\"></i>Cancelled</span><span><i class=\"v2-dot\" style=\"background:#b19cff\"></i>Running / pending</span></div>';\n}\nfunction v2scope(asset,horizon){\n var r=v2rows().find(function(x){return x.asset===asset&&x.horizon===horizon});if(!r){v2info('overlap');return}\n var older=state.training&&Array.isArray(state.training.reports)?state.training.reports.find(function(x){return x.asset===asset&&x.horizon===horizon}):null;\n var receipt=v2receipt(),h=receipt&&receipt.host||{},signed=r.source==='signed-drive-receipt';\n var reason=r.reason==='no_prospective_export'?'No matching prospective export':r.reason==='http_429'?'Historical source rate limit (HTTP 429)':r.reason||'Missing eligibility proof';\n var count=function(x){return x===null||x===undefined?'Not provided in this report':String(x)};\n var prior=older?'<b>Polymarket:</b> '+count(older.pm_history_bars)+' · <b>Kalshi:</b> '+count(older.kalshi_history_bars)+'<div class=\"tiny muted\">Separate Nov 12 historical candidate report. NOT merged into newer live/Drive overlap results.</div>':'No separate historical candidate count available';\n var src=signed&&receipt&&receipt.provenance?receipt.provenance.source_url:'https://github.com/UglyGameFace/RivaL/pull/533';\n show('<div class=\"eyebrow\">XMarket · '+(signed?'signed private Drive report':'archived investigation')+'</div><h2>'+esc(asset)+' · '+horizon+' minute XMarket</h2><div class=\"v2-chip\">'+esc(r.training_status==='blocked'?'BLOCKED IN THIS DATED REPORT':r.gate_passed?'FIT GATES PASSED IN REPORT':'EVIDENCE INCOMPLETE')+'</div><p>Each row is timestamped evidence, not a claim about the live model right now. A blocked training gate is protective.</p>'+\n field('Report captured / modified',esc(v2stamp(r.evidence_date))+' · '+esc(r.source))+\n field('Historical candidate bars (independent older report)',prior)+\n field('Polymarket history status',esc(r.pm_status||'Not included in the chosen report'))+\n field('Kalshi history status',esc(r.kalshi_status||'Not included in the chosen report'))+\n field('Independently matched bars in chosen report','Polymarket: '+count(r.pm_pairs)+' · Kalshi: '+count(r.kalshi_pairs))+\n field('Eligible training rows',count(r.eligible_rows))+\n field('Actual report blocker',esc(reason))+\n field('Host-side model import at latest check',h.xmarket_imported_scopes==null?'Unknown':String(h.xmarket_imported_scopes)+' total XMarket scopes at '+date(receipt.captured_at)+'; not proof about this exact model')+\n field('Exact artifact hash','Not included in either training report; do not infer publication from Drive report metadata')+\n field('Source provenance',src?link(src,signed?'Open signed publisher run':'Historical investigation #533'):'Source not available')+\n '<div class=\"v2-detail-note\">Next source check: completed-day export with paired timestamps, eligible fit, model publish hash, and matching imported model hash. Shadow forecasts and after-cost outcomes are later independent gates.</div>');\n}\nfunction v2matrix(){\n var rows=v2rows();if(rows.length===0)return '<div class=\"v2-empty\">Historical per-scope details are not available.</div>';\n return '<div class=\"v2-matrix\">'+['BTC','ETH','SOL','XRP'].map(function(asset){\n return '<div class=\"v2-asset\"><strong>'+asset+'</strong><div class=\"v2-horizons\">'+[5,15,60].map(function(h){\n var x=rows.find(function(r){return r.asset===asset&&r.horizon===h});\n var c=!x?'unknown':x.training_status==='blocked'?'':x.gate_passed?'good':'unknown';\n return '<button class=\"v2-cell '+c+'\" onclick=\"v2scope(\\''+asset+'\\','+h+')\" title=\"'+asset+' '+h+' minute scope, '+(x?x.training_status:'unknown')+' in the selected dated report\">'+h+'m</button>';\n }).join('')+'</div><div class=\"tiny muted\" style=\"margin-top:7px\">Tap timeframe to see why</div></div>';\n }).join('')+'</div><div class=\"v2-legend\" style=\"margin-top:11px\"><span><i class=\"v2-dot\" style=\"background:#804356\"></i>Blocked in that report</span><span><i class=\"v2-dot\" style=\"background:#377463\"></i>Passed in that report</span><span><i class=\"v2-dot\" style=\"background:#536174\"></i>Unknown</span></div>';\n}\nvar v2oldMatrix=matrix;\nmatrix=function(){return v2matrix()};\nproofGrid=function(){\n var r=v2receipt(),rows=v2rows(),host=r&&r.host||{};\n var found=rows.length===12,paired=found?rows.some(function(x){return x.pm_pairs>0&&x.kalshi_pairs>0}):null;\n return '<div class=\"evidence-grid\">'+\n proof('Matching historical bars',found?(paired?'VERIFIED':'BLOCKED'):'UNKNOWN',found?'Nov 12 report set':'Report unavailable')+\n proof('Provider fidelity',found?'BLOCKED':'UNKNOWN','No matched prospective evidence in those reports')+\n proof('Training fit',found?'BLOCKED':'UNKNOWN',found?'0 passing fits in 12 reports':'Unknown')+\n proof('Drive model publish','UNKNOWN','Reports exist; model file receipt absent')+\n proof('Host model import',host.xmarket_imported_scopes===0?'REPORTED':'UNKNOWN','Host receipt: '+v2stamp(r&&r.captured_at))+\n proof('Issued shadow rows',host.xmarket_shadow_rows===0?'REPORTED':'UNKNOWN','Host receipt: '+v2stamp(r&&r.captured_at))+\n '</div>';\n};\nfunction v2visuals(){\n return '<div class=\"v2-section\"><h2>The XMarket research pipeline</h2><p class=\"small\">Each square is a separate checkpoint. Market feeds and training data are not the same thing. Values belong to dated evidence, not current trading.</p>'+v2pipeline()+'<div class=\"v2-summary\"><b>Why was it blocked?</b> The Nov 12 reports had historical candidates but no matching prospective bars. New signed reports replace the pipeline status when their evidence is newer; the historical comparison graph stays dated. <button class=\"v2-mini-action\" onclick=\"v2info(\\'blocker\\')\">Explain the blockage →</button></div></div>'+\n '<div class=\"v2-section\"><div class=\"v2-graphs\"><div class=\"v2-panel v2-chart\"><h2>Historical prices found, but no usable overlap</h2><p class=\"small\">Number of historical candidate feature bars in the Nov 12 reports. These bars are <b>not</b> verified training examples.</p><div class=\"v2-legend\"><span><i class=\"v2-dot\" style=\"background:#6ed7df\"></i>Polymarket</span><span><i class=\"v2-dot\" style=\"background:#aa91ef\"></i>Kalshi</span><span><i class=\"v2-dot\" style=\"background:#d8b678\"></i>Matching live bars: 0 in each report</span></div>'+v2historyGraph()+'<div class=\"v2-date\">Historical report snapshot: '+esc(v2stamp(state.training&&state.training.verified_at))+'</div></div>'+\n '<div class=\"v2-panel v2-chart\"><h2>GitHub checks, not prediction accuracy</h2><p class=\"small\">Recent CI/release/research workflow outcomes from the fetched GitHub window. Tap a bar for its real run.</p>'+v2workflowGraph()+'<div class=\"v2-line\"></div><h2>Prediction-quality trend</h2><div class=\"v2-detail-note\">'+((state.evidence&&state.evidence.performance&&state.evidence.performance.scopes||[]).length?'Verified paired scores exist below for specific assets and horizons. These are rolling, overlapping score samples, not a statistically independent improvement trend or after-cost advantage.':'No matched forward score receipts are available for a valid improvement chart.')+'</div></div></div></div>';\n}\noverview=function(){\n var receipt=v2receipt(),h=receipt&&receipt.host||{},db=receipt&&receipt.database||{},train=v2rows();\n var healthy=h.status==='verified';\n var snapshot=receipt&&receipt.captured_at;\n var blocked=train.filter(function(x){return x.training_status==='blocked'}).length;\n return '<section class=\"v2-lede\"><div class=\"v2-kicker\">Your research command center</div><h2>What is RivaL actually accomplishing?</h2><p>A simple, visual answer to four questions: Is it healthy, is it learning, is it improving, and what is holding the next model back?</p><span class=\"v2-stamp\">Last private-source receipt: '+esc(v2stamp(snapshot))+' ('+sourceAgeText(snapshot)+') · '+(receipt&&receipt.provenance&&receipt.provenance.method==='github-actions-oidc'?'Signed verified snapshot':'Historical manual snapshot; automatic receipt not yet proven')+'</span></section>'+\n '<div class=\"v2-insights\">'+\n v2line('01 · Is the bot working?',healthy?'Healthy at last check':'Live health unknown',healthy?'Discloud reported fresh forecast and learning cycles at the receipt time. Current uptime still needs a newer check.':'Production host proof is unavailable. GitHub success is not bot uptime.','health')+\n v2line('02 · Is it learning?',db.weight_updates_observed!=null?db.weight_updates_observed+' streams updated':'Learning unknown',db.weight_updates_observed!=null?'Real model-weight changes were recorded in PostgreSQL. This does NOT mean XMarket has a trained model yet.':'No verified online-weight update receipt is available.','learning')+\n v2line('03 · Are predictions better?',db.qualified_paper_scopes===0?'No proven edge yet':'Edge unverified','No scope in the last paper-trading proof passed all after-cost, baseline and sample gates. That does not mean all models are inaccurate.','quality')+\n v2line('04 · What needs fixing?',train.length?blocked+'/'+train.length+' reports blocked':'Training unknown','In those dated XMarket reports, matched data was missing. The historical-data join needs investigation before fitting.','blocker')+\n '</div>'+\n v2visuals()+\n '<section class=\"v2-section\"><div class=\"v2-panel\"><h2>Where is each XMarket experiment stuck?</h2><p class=\"small\">Tap an asset and timeframe to see the actual reason, supporting numbers, and safest next check. These are <b>November 12 historical report results</b>, not permanent failure labels.</p>'+v2matrix()+'</div></section>'+\n '<section class=\"v2-section\"><h2>What we should verify next</h2><div class=\"v2-next\"><div><b>1. Completed-day source export</b>Confirm a real prospective report contains paired market and feature-bar timestamps.</div><div><b>2. Passing model and import</b>Verify a fitted model artifact, Drive publication hash and exact host import.</div><div><b>3. Future shadow performance</b>Count issued and settled forecasts, then compare with the incumbent and market after costs.</div></div></section>'+\n '<section class=\"v2-section\"><div class=\"v2-callout\"><strong>About the scary red labels</strong><div>“Blocked” means the model refused to train on unverified data in that historical report. It is a protective gate, not proof the whole bot crashed. <button class=\"v2-mini-action\" onclick=\"v2info(\\'all\\')\">Learn the status colors →</button></div></div></section>'+\n '<details class=\"deeper\" id=\"techdetails\"><summary><span>Advanced checks, source receipts and research queues</span><span class=\"tiny muted\">Optional</span></summary><div class=\"inner\">'+sourcePanel()+\n '<div class=\"v2-section\"><h2>Proof checklist</h2>'+proofGrid()+'</div>'+\n '<div class=\"v2-section\" id=\"workqueue\"><h2>Research work queues</h2><div class=\"btnrow\" id=\"viewbuttons\"></div><div id=\"viewlist\"></div></div>'+\n '</div></details>';\n};\nevidencePage=function(){\n var r=v2receipt(),d=r&&r.drive||{},rows=v2rows();\n return '<section class=\"v2-lede\"><div class=\"v2-kicker\">Understand your evidence</div><h2>What do we know, and what is still missing?</h2><p>The data below comes from dated research reports and read-only host receipts. We verify each stage separately so a green workflow cannot be mistaken for a working, profitable model.</p><span class=\"v2-stamp\">Private-source receipt: '+esc(v2stamp(r&&r.captured_at))+'</span></section>'+\n sourcePanel()+\n '<div class=\"v2-section\"><h2>Why the reports show red</h2><div class=\"v2-callout\"><strong>The safety gate worked as intended for these runs.</strong><div>The 12 Nov 12 reports do contain historical price candidates but <b>0 matching prospective feature bars</b>. This means XMarket could not verify source fidelity or train an eligible model at that point. A retryable Kalshi HTTP 429 was also recorded. <button class=\"v2-mini-action\" onclick=\"v2info(\\'rate\\')\">What is 429? →</button></div></div></div>'+\n v2visuals()+\n '<div class=\"v2-section\"><div class=\"v2-panel\"><h2>Every asset and timeframe</h2><p class=\"small\">Tap any red timeframe to see the exact historical values.</p>'+v2matrix()+'</div></div>'+\n '<div class=\"v2-section\"><h2>Proof checklist</h2>'+proofGrid()+'</div>'+\n '<div class=\"v2-section\"><div class=\"v2-panel\"><h2>Source connectivity vs missing proof</h2><p><b>Connected snapshot:</b> Discloud cycle receipts, PostgreSQL learning counters, and Drive report metadata. No private passwords or raw documents are sent to this website.</p><p><b>Still missing independent proof:</b> exact host deployment SHA, model artifact publication hashes, matched model-import hashes, and cost-adjusted out-of-sample edge.</p><p><b>Workflow monitoring:</b> '+link('https://github.com/UglyGameFace/RivaL/actions/workflows/evidence-board-receipt.yml','signed evidence collection workflow')+' · '+link('https://github.com/UglyGameFace/RivaL/actions/runs/43224850573','archive run')+' · '+link('https://github.com/UglyGameFace/RivaL/pull/533','history investigation')+'.</p></div></div>'+\n '<div class=\"v2-faq v2-section\"><h2>Common questions</h2>'+\n '<details><summary>Why are there historical bars but no training examples?</summary><p>A model needs independently matched contract/time features, not just old prices. The reports found candidate history but could not match it to their prospective observation window.</p></details>'+\n '<details><summary>Does the HTTP 429 mean Kalshi is broken?</summary><p>No. It means the backfill request was rate-limited. All 12 reports mention the same kind of retryable source error, not 12 confirmed separate outages.</p></details>'+\n '<details><summary>Are 102 updated streams the same as 102 profitable models?</summary><p>No. Those are model-weight update observations from one older PostgreSQL receipt. Prediction quality requires separate settled outcomes, proper baselines, costs and uncertainty.</p></details>'+\n '<details><summary>Why can’t I see an accuracy graph?</summary><p>We do not yet have a trustworthy connected series of paired settled outcomes and baselines. The chart stays empty rather than drawing invented accuracy numbers.</p></details>'+\n '</div>';\n};\n\n\n/* Second-stage verified research evidence: never merge separate proof types. */\nstate.history={source:'unavailable',points:[]};\nvar priorEvidenceRead=readEvidence;\nreadEvidence=function(){\n return priorEvidenceRead().then(function(){\n   var d=state.evidence&&state.evidence.intelligence;\n   state.intPrs=d&&d.status==='verified'&&Array.isArray(d.prs)?d.prs:[];\n   render();\n });\n};\nfunction loadEvidenceHistory(){\n fetch('/api/evidence-history',{cache:'no-store'})\n .then(function(r){if(!r.ok)throw Error('history source unavailable');return r.json()})\n .then(function(x){state.history=x&&Array.isArray(x.points)?x:{source:'unavailable',points:[]};render()})\n .catch(function(){state.history={source:'unavailable',points:[]};render()});\n}\nvar previousEvidenceRefresh=refresh;\nrefresh=function(){previousEvidenceRefresh();loadEvidenceHistory()};\nfunction scoreBox(){\n var source=state.evidence,perf=source&&source.performance,rows=perf&&perf.scopes||[];\n var when=perf&&perf.captured_at;\n var html='<section class=\"v2-section\"><div class=\"v2-panel\"><div class=\"secthead\"><h2>Settled prediction scores</h2>'+\n tag(rows.length?'PAIRED SOURCE EVIDENCE':'AWAITING PAIRED SCORES',rows.length?'ok':'pending')+'</div>'+\n '<p class=\"small\">Model and baseline score the <b>same settled targets</b>. Lower Brier score is better. This does not measure fees, slippage, profit or statistical superiority.</p>';\n if(!rows.length)html+='<div class=\"v2-empty\">No signed, independently paired model-versus-baseline Brier receipt yet. The graph will appear only when the production database returns valid settled observations. An empty chart is not a zero score.</div>';\n else{\n  html+='<div class=\"v2-legend\"><span><i class=\"v2-dot\" style=\"background:#6ed7df\"></i>Persistent logistic model</span><span><i class=\"v2-dot\" style=\"background:#aa91ef\"></i>Baseline on the exact same targets</span></div>';\n  html+='<div class=\"v2-score-grid\">'+rows.map(function(r){\n    var mod=Math.max(0,Math.min(1,r.model_brier)),base=Math.max(0,Math.min(1,r.baseline_brier));\n    var difference=mod-base;\n    return '<div class=\"v2-score\"><div class=\"item-top\"><strong>'+esc(r.asset)+' · '+esc(r.horizon)+'m</strong>'+tag(r.paired_outcomes+' settled pairs','pending')+'</div>'+\n      '<div class=\"v2-score-label\">Model · '+mod.toFixed(3)+'</div><div class=\"v2-score-track\"><span style=\"width:'+(mod*100)+'%;background:#6ed7df\"></span></div>'+\n      '<div class=\"v2-score-label\">Baseline · '+base.toFixed(3)+'</div><div class=\"v2-score-track\"><span style=\"width:'+(base*100)+'%;background:#aa91ef\"></span></div>'+\n      '<div class=\"tiny muted\">Difference '+(difference>=0?'+':'')+difference.toFixed(3)+' · '+(difference<0?'model lower in this sample':'no demonstrated model advantage in this sample')+'</div></div>';\n  }).join('')+'</div><div class=\"v2-date\">Read-only paired PostgreSQL audit · '+esc(date(when))+' · most recent 24h · up to 500 rows per asset · not after-cost qualified</div>';\n }\n var points=state.history&&Array.isArray(state.history.points)?state.history.points:[];\n html+='<div class=\"v2-section\"><h2>Verified evidence over time</h2><p class=\"small\">Each point is a different signed collector run. We never connect unrelated assets/models into a fake winning trend.</p>';\n var good=points.filter(function(p){return p&&p.performance&&Array.isArray(p.performance.scopes)&&p.performance.scopes.length});\n if(good.length<2)html+='<div class=\"v2-empty\">'+(good.length===1?'One signed scoring snapshot exists; at least two comparable observations are needed for a trend.':'No multiple comparable signed scoring snapshots yet. This graph starts when the hourly collector supplies them.')+'</div>';\n else{\n  var groups={};good.forEach(function(p){p.performance.scopes.forEach(function(r){var key=r.asset+' '+r.horizon+'m';(groups[key]=groups[key]||[]).push({at:p.captured_at,n:r.paired_outcomes,m:r.model_brier,b:r.baseline_brier})})});\n  var key=Object.keys(groups).sort().find(function(k){return groups[k].length>=2});\n  if(!key)html+='<div class=\"v2-empty\">There are signed observations, but none cover the same asset and horizon twice. No valid trend line yet.</div>';\n  else{\n   var d=groups[key].slice(-18),n=d.length,w=620,hei=170;\n   var x=function(i){return 26+(w-50)*i/(n-1)},y=function(v){return 143-120*v};\n   var mk=function(k,color){return '<polyline fill=\"none\" stroke=\"'+color+'\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\" points=\"'+d.map(function(p,i){return x(i).toFixed(1)+','+y(p[k]).toFixed(1)}).join(' ')+'\"/>'+d.map(function(p,i){return '<circle cx=\"'+x(i).toFixed(1)+'\" cy=\"'+y(p[k]).toFixed(1)+'\" r=\"3.5\" fill=\"'+color+'\"><title>'+esc(date(p.at))+' · '+esc(key)+' · '+k+' '+p[k].toFixed(3)+' · n '+p.n+'</title></circle>'}).join('')};\n   html+='<p class=\"small\">Consistent scope: '+esc(key)+' · '+n+' signed snapshots. Same rolling 24-hour score measure, changing sample windows.</p><div style=\"overflow:auto\"><svg viewBox=\"0 0 620 170\" width=\"100%\" style=\"min-width:320px\" role=\"img\" aria-label=\"Paired Brier scores across signed snapshots\"><line x1=\"25\" y1=\"143\" x2=\"595\" y2=\"143\" stroke=\"#657186\"/>'+mk('m','#6ed7df')+mk('b','#aa91ef')+'</svg></div>';\n  }\n }\n html+='</div><div class=\"callout\">A score can look better by chance. Promotion still needs sufficient independent outcomes, source/quote coverage, 21 days, comparison with the incumbent, realistic costs, and corrected uncertainty. No trade or promotion action is available here.</div></div></section>';\n return html;\n}\nfunction intelligenceBox(){\n var d=state.evidence,info=d&&d.intelligence||{},age=d&&d.captured_at;\n var valid=info.status==='verified',runs=Array.isArray(info.runs)?info.runs:[];\n var host=info.host_status||'unavailable';\n return '<section class=\"v2-section\"><div class=\"v2-panel\"><div class=\"secthead\"><h2>RivaL Intelligence · independent evidence</h2>'+\n tag(valid?'PUBLIC GITHUB VERIFIED':'AWAITING PUBLIC SNAPSHOT',valid?'ok':'pending')+'</div>'+\n '<p class=\"small\">The Intelligence code repository is public. Its GitHub CI, Discloud container, and real model-inference reliability are separate checks.</p>'+\n '<div class=\"v2-road\">'+\n v2stage('Intelligence source code',valid?1:null,1,valid?'GitHub commit '+esc((info.head_sha||'').slice(0,10)):'Repository snapshot pending','','all')+\n v2stage('Latest Intelligence CI',runs.length?(runs[0].conclusion==='success'?1:0):null,1,runs.length?esc(runs[0].conclusion||runs[0].status):'No signed run evidence','','all')+\n v2stage('Intelligence Discloud app',host==='online'?1:host==='offline'?0:null,1,host==='online'?'Provider reported online at check':host==='offline'?'Provider reported offline at check':'Discloud check unavailable','','all')+\n v2stage('Verified inference quality',null,1,'No scored inference-outcome dataset connected','','quality')+\n '</div><div class=\"v2-date\">Source: '+esc(date(info.fetched_at||age))+' · Successful CI does not prove active model inference.</div>'+\n (runs.length?'<div class=\"v2-section\"><h2>Recent Intelligence workflows</h2><div class=\"items\">'+runs.slice(0,4).map(function(r){return '<div class=\"item\"><div class=\"item-top\"><strong>'+link(r.html_url,esc(r.name))+'</strong>'+tag(r.conclusion||r.status,r.conclusion==='success'?'ok':r.conclusion==='failure'?'bad':'pending')+'</div><div class=\"tiny muted\">'+esc(date(r.created_at))+' · Host inference unverified</div></div>'}).join('')+'</div></div>':\n '<div class=\"v2-detail-note\">Waiting for the signed Intelligence GitHub snapshot. No fake runtime counters or accuracy figures are displayed.</div>')+\n '</div></section>';\n}\nvar oldSecondStageOverview=overview;\noverview=function(){\n var body=oldSecondStageOverview(),anchor='<section class=\"v2-section\"><div class=\"v2-panel\"><h2>Where is each XMarket experiment stuck?';\n if(body.includes(anchor))return body.replace(anchor,scoreBox()+intelligenceBox()+anchor);\n return body+scoreBox()+intelligenceBox();\n};\nvar oldSecondStageEvidence=evidencePage;\nevidencePage=function(){return oldSecondStageEvidence()+scoreBox()+intelligenceBox()};\nvar oldSecondStageCI=ciPage;\nciPage=function(){\n var b=oldSecondStageCI(),i=state.evidence&&state.evidence.intelligence;\n if(!i||i.status!=='verified')return b+'<div class=\"v2-detail-note\">RivaL Intelligence CI is not yet available through a signed source receipt.</div>';\n return b+intelligenceBox();\n};\n\nvar boardLastRefresh=Date.now();function refreshBoardIfVisible(){if(document.hidden||Date.now()-boardLastRefresh<50000)return;boardLastRefresh=Date.now();refresh()}window.setInterval(refreshBoardIfVisible,60000);document.addEventListener('visibilitychange',function(){if(!document.hidden){boardLastRefresh=0;refreshBoardIfVisible()}});\nwindow.addEventListener('popstate',function(){take();render()});try{take();render();refresh()}catch(e){document.body.dataset.pageerror=e.name+': '+e.message;document.getElementById('content').innerHTML='<div class=\"v2-empty\">Dashboard could not initialize: '+esc(e.message)+'</div>';}\n</script></body></html>";
const REPOS = ['RivaL','RivaL-Intelligence'];
function response(payload,status=200,cache='public,max-age=60'){return new Response(JSON.stringify(payload),{status,headers:{'content-type':'application/json;charset=utf-8','cache-control':cache,'x-content-type-options':'nosniff','access-control-allow-origin':'*'}})}
async function bootstrap(){try{const r=await RIVAL_EVIDENCE_RECEIPTS.fetch('https://rival-evidence-collector.staytrippynlw.workers.dev/github-snapshot');if(!r.ok)throw Error('GitHub cache HTTP '+r.status);const obj=await r.json();if(!obj||!Array.isArray(obj.prs)||!Array.isArray(obj.runs))throw Error('Verified GitHub snapshot not available');return {source:'github-snapshot',capture_method:obj.method||'snapshot',fetched_at:obj.fetched_at,rival:{prs:obj.prs,runs:obj.runs},intelligence:{prs:[]},errors:[],limitations:obj.limitations||[]}}catch(e){return {source:'unavailable',fetched_at:null,rival:{prs:[],runs:[]},intelligence:{prs:[]},errors:[String(e.message)]}}}
async function publicGithubRunDetails(id){
  const base='https://api.github.com/repos/UglyGameFace/RivaL';
  async function get(path){
    const res=await fetch(base+path,{headers:{'Accept':'application/vnd.github+json','User-Agent':'RivaL-Evidence-Board/1.0'},cf:{cacheEverything:true,cacheTtl:90}});
    if(!res.ok)throw Error('GitHub API HTTP '+res.status);
    return await res.json();
  }
  const attempts=await Promise.allSettled([
    get('/actions/runs/'+id+'/jobs?per_page=30'),
    get('/actions/runs/'+id+'/artifacts?per_page=30')
  ]);
  const errors=[];
  let jobs=null,artifacts=null;
  if(attempts[0].status==='fulfilled'){
    jobs=(attempts[0].value.jobs||[]).slice(0,30).map(j=>({
      id:j.id,name:String(j.name||'').slice(0,180),status:j.status,conclusion:j.conclusion,html_url:j.html_url,
      steps:(j.steps||[]).slice(0,40).map(s=>({name:String(s.name||'').slice(0,160),conclusion:s.conclusion,status:s.status,number:s.number}))
    }));
  }else errors.push('Public GitHub job details unavailable; use the official run link');
  if(attempts[1].status==='fulfilled'){
    artifacts=(attempts[1].value.artifacts||[]).slice(0,30).map(a=>({
      name:String(a.name||'').slice(0,180),expired:!!a.expired,size_in_bytes:Number(a.size_in_bytes||0),
      created_at:a.created_at,expires_at:a.expires_at
    }));
  }else errors.push('Public GitHub artifact list unavailable; absence is not proven');
  return {jobs,artifacts,errors};
}

addEventListener('fetch',e=>{e.respondWith(handle(e.request))});
async function handle(req){const url=new URL(req.url);if(req.method!=='GET'&&req.method!=='HEAD')return response({error:'read-only: method not allowed'},405,'no-store');
if(url.pathname==='/api/evidence-history'){try{const r=await RIVAL_EVIDENCE_RECEIPTS.fetch('https://rival-evidence-collector.staytrippynlw.workers.dev/history');if(!r.ok)return response({source:'unavailable',points:[]},503);const data=await r.json();return response(data,200,'public,max-age=60');}catch(_){return response({source:'unavailable',points:[]},503)}}
if(url.pathname==='/api/source-evidence'){try{const r=await RIVAL_EVIDENCE_RECEIPTS.fetch('https://rival-evidence-collector.staytrippynlw.workers.dev/latest');if(!r.ok)return response({status:'unavailable',error:'source_unavailable'},503);const obj=await r.json();return response(obj,200,'public,max-age=25');}catch(_){return response({status:'unavailable',error:'receipt_unavailable'},503)}}
if(url.pathname==='/api/training-snapshot'){try{const r=await RIVAL_EVIDENCE_RECEIPTS.fetch('https://rival-evidence-collector.staytrippynlw.workers.dev/training-snapshot');if(!r.ok)return response({status:'unavailable'},503);return response(await r.json(),200,'public,max-age=300');}catch(_){return response({status:'unavailable'},503)}}
if(url.pathname==='/api/bootstrap'){return response(await bootstrap(),200,'public,max-age=60,stale-while-revalidate=120')}
if(url.pathname==='/api/run'){
 const id=url.searchParams.get('id');
 if(!/^\d{1,15}$/.test(id||''))return response({error:'Invalid run ID'},400,'no-store');
 const snapshot=await bootstrap(),run=(snapshot.rival?.runs||[]).find(x=>String(x.id)===id);
 if(!run)return response({source:'not-in-signed-snapshot',error:'Run not in the latest bounded signed GitHub window; open its official GitHub page'},404);
 const details=await publicGithubRunDetails(id);
 return response({source:'public-github-api',run,...details,limitations:['Jobs and artifacts are publicly fetched live from GitHub; this is not part of the signed source snapshot.','No private logs, secret values, or action mutations are exposed.']},200,'public,max-age=90');
}
if(url.pathname==='/health')return response({ok:true,service:'RivaL Evidence Board',read_only:true,version:'2026-11-13-sync-status-v2'});
if(url.pathname==='/'||url.pathname==='/index.html')return new Response(req.method==='HEAD'?null:HTML,{headers:{'content-type':'text/html;charset=utf-8','cache-control':'no-store, max-age=0','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin','content-security-policy':"default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; frame-ancestors 'none'"}});
return response({error:'Not found'},404)}
